/* Converti depuis ui_kits/site-public/routes.js (prototype) — ne pas réintroduire de globaux window. */
import { LL_LOCALITES_ROUTES } from '@/proto/localites-routes';
import { LL_ARTICLES } from '@/lib/articles-meta';
const A = ['Accueil', '/'],
  PROP = ['Gestion immobilière', '/gestion-immobiliere'],
  LOC = ['Service aux locataires', '/locataires'];
const F = (lbl, path, extra) => Object.assign({
  path,
  fil: [A, LOC, [lbl, path]],
  index: false,
  schemas: ['WebPage', 'BreadcrumbList'],
  page: 'formulaire',
  liens: ['/locataires', '/logements-a-louer', '/faq']
}, extra);
/* FAQ propre à chaque guide de quartier (affichée sur la page et déclarée en FAQPage). */
const QF = {
  "aeroport": [["Où se trouve le quartier de l’Aéroport?", "Au nord-ouest de la ville de Québec, dans l’arrondissement de Sainte-Foy–Sillery–Cap-Rouge, autour de l’aéroport international Jean-Lesage. Il borde la ville de L’Ancienne-Lorette."], ["D’où vient le nom du quartier de l’Aéroport?", "De l’aéroport international Jean-Lesage, situé au cœur de son territoire. Avant 2002, le secteur s’appelait le quartier Laurentien, un nom que de nombreux résidents utilisent encore."], ["Quels sont les secteurs résidentiels du quartier de l’Aéroport?", "Champigny, Jouvence et Chauveau. Le quartier comprend aussi le secteur agricole des rangs Saint-Ange et Saint-Denis et une petite portion du secteur du lac Saint-Augustin."]],
  "bourg-royal": [["Où se trouve Bourg-Royal?", "Dans l’arrondissement de Charlesbourg, au nord-est de la ville de Québec, entre le boulevard du Loiret, la zone agricole et le mont Reine-Malouin."], ["D’où vient le nom de Bourg-Royal?", "Du village en étoile que l’intendant Jean Talon fait aménager en 1667 sur des terres retirées aux Jésuites. Le Bourg-Royal comptait 29 terres en 1674."], ["Quels parcs se trouvent à Bourg-Royal?", "Le parc de la Montagne-des-Roches, le parc du Bourg-Royal, le parc Saint-Viateur et le parc des Émeraudes."]],
  "breakeyville": [["Où se trouve Breakeyville?", "Sur la Rive-Sud, le long de la rivière Chaudière, au sud de Charny, dans l’arrondissement Les Chutes-de-la-Chaudière-Est de la ville de Lévis."], ["D’où vient le nom de Breakeyville?", "Il rappelle le marchand de bois John Breakey (1846-1911) et son épouse, Helen Henderson, d’où le nom officiel Sainte-Hélène-de-Breakeyville, choisi lors de l’érection de la paroisse en 1908."], ["Comment se rendre à Québec depuis Breakeyville?", "Par l’autoroute 73, qui mène au pont Pierre-Laporte en une dizaine de minutes."]],
  "cap-rouge": [["Où se trouve Cap-Rouge?", "À l’ouest de la ville de Québec, dans l’arrondissement de Sainte-Foy–Sillery–Cap-Rouge. Le quartier s’étend du fleuve Saint-Laurent, au sud, jusqu’à l’autoroute Félix-Leclerc, au nord."], ["D’où vient le nom de Cap-Rouge?", "Du promontoire de schiste rougeâtre situé à l’embouchure de la rivière du Cap Rouge. Le nom est mentionné pour la première fois vers 1638."], ["Qu’est-ce que le tracel de Cap-Rouge?", "Un viaduc ferroviaire à tréteaux qui franchit la vallée de la rivière du Cap Rouge. Sa construction commence en 1906, il est mis en service en 1913 et il est toujours utilisé par le Canadien National."]],
  "charny": [["Où se trouve Charny?", "Sur la rive est de la rivière Chaudière, non loin du pont de Québec, à Lévis. C’est l’un des quatre secteurs de l’arrondissement Les Chutes-de-la-Chaudière-Est."], ["D’où vient le nom de Charny?", "Il rappelle Charles de Lauson, sieur de Charny, arrivé en Nouvelle-France en 1652. Il tenait ce titre de sa grand-mère, fille de Guillaume Lottin, seigneur de Charny, en France."], ["Que voir au parc des Chutes-de-la-Chaudière?", "Les chutes de la Chaudière, hautes de 35 mètres, et une passerelle suspendue de 113 mètres, à 23 mètres au-dessus de la rivière. Le parc compte aussi environ 4,5 km de sentiers et une piste cyclable."]],
  "chutes-montmorency": [["Où se trouve le quartier des Chutes-Montmorency?", "Dans l’est de l’arrondissement de Beauport, à Québec, entre le Vieux-Bourg et la rivière Montmorency, qui le sépare de Boischatel."], ["D’où vient le nom des Chutes-Montmorency?", "De la chute Montmorency, sur la rivière du même nom, à la limite du quartier et de Boischatel. Samuel de Champlain l’a nommée en l’honneur de l’amiral Charles de Montmorency."], ["Quels secteurs forment le quartier des Chutes-Montmorency?", "Les anciennes municipalités de Courville et de Montmorency et la majeure partie de Villeneuve, réunies en 2002 lors de l’annexion de Beauport à Québec."]],
  "cite-universitaire": [["Où se trouve le quartier Cité-Universitaire?", "Dans l’arrondissement Sainte-Foy–Sillery–Cap-Rouge, au sud de la ville de Québec, dans le quadrant sud-est formé par les autoroutes Henri-IV et Charest."], ["Quels établissements d’enseignement trouve-t-on dans la Cité-Universitaire?", "Le campus principal de l’Université Laval, le Cégep Garneau, le Cégep de Sainte-Foy et le Collège régional Champlain St. Lawrence."], ["Quelles sont les grandes artères de la Cité-Universitaire?", "L’autoroute Robert-Bourassa, le boulevard Laurier, le chemin Sainte-Foy, le chemin des Quatre-Bourgeois, le boulevard Hochelaga, le boulevard du Versant-Nord et la route de l’Église."]],
  "des-chatels": [["Où se trouve le quartier des Châtels?", "Dans le nord-ouest de la ville de Québec, à l’ouest et au sud de Loretteville, dans l’arrondissement de La Haute-Saint-Charles. La rivière Saint-Charles marque sa limite au sud-est."], ["D’où vient le nom du quartier des Châtels?", "Il est dérivé de Neufchâtel, l’ancienne ville dont le quartier occupe la partie ouest. Ce nom, adopté en 1963, rend hommage à des résidents qui ont combattu à Neufchâtel-en-Bray, en Normandie, durant la Seconde Guerre mondiale."], ["Quelles sont les artères principales du quartier des Châtels?", "Le boulevard de l’Ormière, l’autoroute Henri-IV, l’avenue Chauveau, le boulevard Bastien, le boulevard des Cimes, le boulevard Saint-Claude et la rue Monseigneur-Cooke."]],
  "duberger-les-saules": [["Où se trouve le quartier Duberger–Les Saules?", "Dans l’arrondissement des Rivières, près du centre géographique de la ville de Québec, tout juste à l’est de L’Ancienne-Lorette."], ["D’où vient le nom Duberger–Les Saules?", "Il réunit les noms des anciennes villes de Duberger et des Saules, annexées à Québec en 1970. Le nom Les Saules vient des nombreux saules qui poussaient le long des rivières Saint-Charles et Lorette."], ["Quelles sont les grandes artères de Duberger–Les Saules?", "Les boulevards Wilfrid-Hamel et Père-Lelièvre, d’est en ouest, le boulevard Masson, ainsi que les autoroutes Robert-Bourassa, Henri-IV, Félix-Leclerc et Charest."]],
  "jesuites": [["Où se trouve le quartier des Jésuites?", "Dans l’arrondissement de Charlesbourg, à Québec, entre le boulevard Henri-Bourassa et le boulevard du Loiret, au sud du boulevard Jean-Talon."], ["D’où vient le nom du quartier des Jésuites?", "Des Jésuites, premiers seigneurs de Notre-Dame-des-Anges, et en particulier du moulin des Jésuites, construit en 1742 et situé dans le quartier."], ["Quelles sont les artères principales du quartier des Jésuites?", "Le boulevard Henri-Bourassa, le boulevard Louis-XIV (route 369), le boulevard du Loiret et l’autoroute Félix-Leclerc (autoroute 40)."]],
  "lac-saint-charles": [["Où se trouve Lac-Saint-Charles?", "Dans le nord de la ville de Québec, dans l’arrondissement de La Haute-Saint-Charles, au nord de Saint-Émile et de Loretteville, autour du lac du même nom."], ["D’où vient le nom de Lac-Saint-Charles?", "Du lac Saint-Charles, qui doit son nom à la rivière Saint-Charles qui s’en écoule. Ce nom rappelle Charles Desboues, bienfaiteur des Récollets arrivés à Québec en 1615."], ["Que faire en plein air à Lac-Saint-Charles?", "Parcourir les huit kilomètres de sentiers de la réserve naturelle des Marais-du-Nord, où l’on peut observer près de 160 espèces d’oiseaux, ou marcher dans le parc linéaire des rivières Saint-Charles et du Berger, qui part du lac."]],
  "lairet": [["Où se trouve le quartier Lairet?", "Dans le secteur de Limoilou, au nord de l’arrondissement de La Cité-Limoilou, juste au sud de Charlesbourg. Il occupe le quadrant sud-est formé par les autoroutes Félix-Leclerc et Laurentienne."], ["D’où vient le nom de Lairet?", "De la rivière Lairet, un affluent de la rivière Saint-Charles aujourd’hui presque entièrement canalisé. L’origine du nom de la rivière est incertaine : on l’attribue parfois à un des premiers résidents de Charlesbourg, parfois au Loiret, un affluent de la Loire."], ["Qu’y a-t-il sur le site d’ExpoCité?", "Le Centre Vidéotron, le Centre de foires, le pavillon Guy-Lafleur, le Grand Marché de Québec et l’ancien Colisée de Québec, ouvert en 1949 et fermé en 2015. Le site accueille des salons, des spectacles et des événements sportifs."]],
  "lauzon": [["Où se trouve Lauzon?", "Sur la Rive-Sud, au bord du fleuve Saint-Laurent, face à l’île d’Orléans, dans l’arrondissement Desjardins de la ville de Lévis. C’est une ancienne ville, fusionnée à Lévis en 1989."], ["D’où vient le nom de Lauzon?", "Il rappelle Jean de Lauson, premier concessionnaire de la seigneurie de Lauzon en 1636 et gouverneur de la Nouvelle-France. Le nom a été choisi en 1867 pour éviter la confusion avec la ville voisine de Lévis."], ["Comment se rendre à Québec depuis Lauzon?", "La traverse Québec-Lévis part du Vieux-Lévis, tout près, et rejoint le Vieux-Québec. En voiture, le pont de Québec et le pont Pierre-Laporte se trouvent dans l’ouest de Lévis."]],
  "loretteville": [["Où se trouve le quartier Loretteville?", "Dans le nord-ouest de la ville de Québec, le long de la rivière Saint-Charles, dans l’arrondissement de La Haute-Saint-Charles. Le quartier entoure Wendake."], ["D’où vient le nom de Loretteville?", "Il rappelle la Jeune-Lorette, l’établissement des Hurons-Wendats arrivés à la fin du XVIIe siècle depuis leur site de Lorette, aujourd’hui L’Ancienne-Lorette. Le village de Saint-Ambroise adopte le nom de Loretteville en 1913."], ["Quels parcs se trouvent à Loretteville?", "Le parc de la falaise et de la chute Kabir Kouba, le parc linéaire des rivières Saint-Charles et du Berger, les parcs Johnny-Parent, Gaby-Pleau et Jean-Roger-Durand, ainsi que la piste cyclable des Cheminots."]],
  "maizerets": [["Où se trouve le quartier Maizerets?", "À l’est du secteur de Limoilou, dans l’arrondissement de La Cité-Limoilou, entre le fleuve Saint-Laurent et l’autoroute Félix-Leclerc. Il borde l’arrondissement de Beauport."], ["D’où vient le nom de Maizerets?", "Du Domaine de Maizerets, nommé au milieu du XIXe siècle en l’honneur de Louis Ango de Maizerets, supérieur du Séminaire de Québec à l’époque où celui-ci a acquis ces terres. Le secteur s’appelait auparavant la Canardière."], ["Que faire au Domaine de Maizerets?", "Marcher sur 11 km de sentiers, visiter l’arboretum aménagé en 1997 et, en hiver, faire du ski de fond, de la raquette ou du patin. L’accès au parc est gratuit."]],
  "notre-dame-des-laurentides": [["Où se trouve Notre-Dame-des-Laurentides?", "Dans le nord de l’arrondissement de Charlesbourg, au nord de la rue de la Faune. Le quartier touche à la municipalité de Lac-Beauport, à l’est."], ["D’où vient le nom de Notre-Dame-des-Laurentides?", "D’une statue de Notre-Dame de Lourdes achetée par le notable George Muir, qui a aussi financé le couvent des Sœurs du Bon-Pasteur en 1871 et une chapelle en 1875."], ["Quelles routes traversent Notre-Dame-des-Laurentides?", "L’autoroute Laurentienne (73), le boulevard Henri-Bourassa et le boulevard du Lac le traversent du sud au nord. Le boulevard Talbot (route 175) fait aussi partie de ses artères."]],
  "orsainville": [["Où se trouve le quartier Orsainville?", "Dans l’arrondissement de Charlesbourg, entre le boulevard Jean-Talon au sud, la rue de la Faune au nord, l’autoroute Laurentienne (73) à l’ouest et le boulevard du Loiret à l’est."], ["D’où vient le nom d’Orsainville?", "Du comté d’Orsainville, un fief situé à proximité à l’époque de la Nouvelle-France. La municipalité de Saint-Charles-de-Charlesbourg prend ce nom en 1953."], ["Quels parcs trouve-t-on à Orsainville?", "Le parc des Moulins, créé en 2006 sur une partie de l’ancien Jardin zoologique du Québec, le parc linéaire de la Rivière-des-Roches et les parcs Saint-Pierre, Chabot, des Verveines, du Périgord et du Lyonnais."]],
  "pintendre": [["Où se trouve Pintendre?", "Sur la Rive-Sud, à environ 5 km au sud du centre de Lévis, de part et d’autre de la route 173, dans l’arrondissement Desjardins de la ville de Lévis."], ["D’où vient le nom de Pintendre?", "L’hypothèse retenue évoque d’anciennes forêts de pins blancs, un bois tendre; sous le Régime français, pin s’écrivait souvent « pain ». Le nom « Pain Tendre » est attesté dès 1757."], ["Quels parcs se trouvent à Pintendre?", "Le parc du Lac-Baie-d’Or, le Site des Pins, au bout de la route Monseigneur-Lagueux, le parc Olympique et le parc des Petits-Jardins."]],
  "plateau": [["Où se trouve le quartier du Plateau?", "Dans l’arrondissement Sainte-Foy–Sillery–Cap-Rouge, au sud de la ville de Québec, en grande partie entre les autoroutes Duplessis et Henri-IV."], ["D’où vient le nom du chemin des Quatre-Bourgeois?", "Il rend hommage aux quatre propriétaires terriens dont les terres ont servi à ouvrir la voie, tracée vers 1850 par Daniel Ross. La Ville de Sainte-Foy a officialisé ce nom le 4 mai 1950."], ["Quelles sont les grandes artères du Plateau?", "Les autoroutes Duplessis et Henri-IV, le chemin des Quatre-Bourgeois, le chemin Sainte-Foy, le boulevard du Versant-Nord, le boulevard Hochelaga et l’avenue Duchesneau."]],
  "pointe-de-sainte-foy": [["Où se trouve la Pointe-de-Sainte-Foy?", "À l’extrémité ouest de la colline de Québec, dans l’ancienne ville de Sainte-Foy, dans l’arrondissement de Sainte-Foy–Sillery–Cap-Rouge. Le quartier Cap-Rouge se trouve à l’ouest."], ["D’où vient le nom de la Pointe-de-Sainte-Foy?", "Le quartier occupe l’extrémité ouest de la colline de Québec, qui forme une pointe vers Cap-Rouge."], ["Quels boisés et parcs trouve-t-on à la Pointe-de-Sainte-Foy?", "Le boisé de Marly, le boisé des Compagnons-de-Cartier, le boisé Neilson, le parc du Campanile et le parc Saint-Benoît. Le parc de la Plage-Jacques-Cartier, au bord du fleuve, est tout près."]],
  "saint-emile": [["Où se trouve le quartier Saint-Émile?", "Dans le nord de la ville de Québec, au nord-est de Loretteville et près de Wendake, dans l’arrondissement de La Haute-Saint-Charles."], ["D’où vient le nom de Saint-Émile?", "Le nom apparaît en 1904 avec le bureau de poste Saint-Émile-de-Québec. La paroisse, érigée en 1925, est placée sous le vocable de saint Émile, un martyr de Carthage du IIIe siècle."], ["Quels parcs se trouvent à Saint-Émile?", "Notamment les parcs de la Grande-Oasis, de la Petite-Oasis, Réal-Cloutier, Roy, de la Colline, du Millénaire, du Vignoble et des Quatre-Vents."]],
  "saint-etienne-de-lauzon": [["Où se trouve Saint-Étienne-de-Lauzon?", "Au sud de Saint-Nicolas, de part et d’autre de la rivière Beaurivage, à l’ouest de la rivière Chaudière. C’est l’un des trois secteurs de l’arrondissement Les Chutes-de-la-Chaudière-Ouest, à Lévis."], ["D’où vient le nom de Saint-Étienne-de-Lauzon?", "Il rappelle l’abbé Étienne Baillargeon, curé de Saint-Nicolas de 1838 à 1870, qui a travaillé à la création de la paroisse. « Lauzon » marque l’appartenance du territoire à l’ancienne seigneurie de Lauzon."], ["Quels parcs se trouvent à Saint-Étienne-de-Lauzon?", "Les parcs des Grandes-Pointes, Ludger-Bastien, des Aînés, Jean-de-Lauzon, Gilles-Rageot, Martin et de L’Art-de-Vivre."]],
  "saint-jean-baptiste": [["Où se trouve le quartier Saint-Jean-Baptiste?", "Dans la haute-ville de Québec, entre le Vieux-Québec et Montcalm, au-dessus du coteau Sainte-Geneviève qui le sépare de Saint-Roch. Il fait partie de l’arrondissement de La Cité-Limoilou."], ["Pourquoi l’appelle-t-on aussi le faubourg Saint-Jean?", "Le quartier couvre l’ancien faubourg Saint-Jean, né sous le Régime français le long du chemin Saint-Jean, à l’extérieur de la porte Saint-Jean. Il englobe aussi l’ancien faubourg Saint-Louis, au sud de la rue Saint-Patrick."], ["Comment rejoindre Saint-Roch à pied depuis Saint-Jean-Baptiste?", "Par les escaliers du coteau Sainte-Geneviève, dont les escaliers Lavigueur, Badelard, du Faubourg, de la Chapelle et Lépine, ou par l’ascenseur du Faubourg."]],
  "saint-jean-chrysostome": [["Où se trouve Saint-Jean-Chrysostome?", "Sur la Rive-Sud, dans l’arrondissement Les Chutes-de-la-Chaudière-Est de la ville de Lévis, au sud de Saint-Romuald et à l’est de Charny, entre les rivières Chaudière et Etchemin."], ["D’où vient le nom de Saint-Jean-Chrysostome?", "De la paroisse créée en 1828, qui honore saint Jean Chrysostome, archevêque de Constantinople, et rappelle sir John Caldwell, seigneur de Lauzon. Auparavant, une partie du territoire s’appelait Taniata."], ["Quelles routes traversent Saint-Jean-Chrysostome?", "Les autoroutes 20 (Jean-Lesage) et 73 (Robert-Cliche), l’avenue Taniata (route 275) et la route 175. L’autoroute 73 mène au pont Pierre-Laporte, vers Québec."]],
  "saint-joseph-de-la-pointe-de-levy": [["Où se trouve Saint-Joseph-de-la-Pointe-De Lévy?", "Sur la Rive-Sud, au sud de Lauzon et au sud-est du centre de Lévis, dans l’arrondissement Desjardins de la ville de Lévis."], ["D’où vient le nom de Saint-Joseph-de-la-Pointe-De Lévy?", "De la paroisse fondée en 1679 sous le patronage de saint Joseph, et de la pointe de Lévy, nommée d’après Henri de Lévis, duc de Ventadour. La graphie « De Lévy » tient compte de la particule nobiliaire."], ["Quelle est la différence avec Lauzon?", "Les deux faisaient partie de la même paroisse. En 1867, le village de Lauzon, le long du fleuve, s’en est détaché; le reste du territoire, plus rural, forme l’actuel secteur."]],
  "saint-louis": [["Où se trouve le quartier Saint-Louis?", "Dans l’arrondissement Sainte-Foy–Sillery–Cap-Rouge, au sud de la ville, à la tête des ponts de Québec et Pierre-Laporte. Il ne faut pas le confondre avec le faubourg Saint-Louis, près du Vieux-Québec."], ["D’où vient le nom de Saint-Louis?", "Du chemin Saint-Louis et de la paroisse Saint-Louis-de-France, fondée en 1956 et nommée en l’honneur de Louis IX, roi de France de 1226 à 1270."], ["Comment se rendre à Saint-Louis?", "Par les autoroutes Henri-IV et Duplessis, le boulevard Laurier ou le chemin Saint-Louis. Depuis la Rive-Sud, les ponts de Québec et Pierre-Laporte y aboutissent, et la gare de Sainte-Foy accueille trains et autocars."]],
  "saint-michel": [["Où se trouve le quartier Saint-Michel?", "Dans le nord de l’arrondissement de Beauport, à Québec, entre l’autoroute Félix-Leclerc au sud et le boulevard Louis-XIV au nord, à l’est de la rivière Beauport."], ["D’où vient le nom du quartier Saint-Michel?", "De l’avenue Saint-Michel, l’une de ses principales artères. Elle rappelle l’ancien rang Saint-Michel, ouvert dans la seigneurie de Beauport à partir des années 1670."], ["Quelles sont les artères principales de Saint-Michel?", "L’autoroute Félix-Leclerc, la rue Seigneuriale, le boulevard Louis-XIV, le boulevard Raymond et l’avenue Saint-Michel."]],
  "saint-nicolas": [["Où se trouve Saint-Nicolas?", "Sur la rive sud du Saint-Laurent, à l’ouest de la rivière Chaudière, à Lévis. C’est l’un des trois secteurs de l’arrondissement Les Chutes-de-la-Chaudière-Ouest, avec Saint-Rédempteur et Saint-Étienne-de-Lauzon."], ["D’où vient le nom de Saint-Nicolas?", "Le nom est attribué en 1694 à la demande de Claude de Bermen de La Martinière, qui voulait rappeler sa paroisse d’origine, Saint-Nicolas-de-la-Ferté, en France. Il évoque aussi saint Nicolas, évêque du IVe siècle."], ["Qu’est-ce que le site du patrimoine de Saint-Nicolas?", "Un petit ensemble de maisons anciennes, surtout sur la route Marie-Victorin, désigné en 1987. Il comprend la maison Pâquet, construite vers 1760, et la chapelle Notre-Dame-de-Grâce, de 1867-1868."]],
  "saint-redempteur": [["Où se trouve Saint-Rédempteur?", "Sur la rive ouest de la rivière Chaudière, au confluent de la Beaurivage, entre Saint-Nicolas et Charny. C’est l’un des trois secteurs de l’arrondissement Les Chutes-de-la-Chaudière-Ouest, à Lévis."], ["D’où vient le nom de Saint-Rédempteur?", "Il reprend celui de la paroisse de Très-Saint-Rédempteur, érigée en 1919. Le nom fait allusion à un titre du Christ, le Sauveur de l’humanité."], ["Comment se rendre à Saint-Rédempteur?", "Par l’autoroute 20, sortie 311, puis la route 116, appelée route des Rivières dans le secteur. Les ponts de Québec et Pierre-Laporte sont à moins de 5 km."]],
  "saint-rodrigue": [["Où se trouve Saint-Rodrigue?", "Dans le sud de l’arrondissement de Charlesbourg, à Québec, en bordure des autoroutes Laurentienne et Félix-Leclerc."], ["D’où vient le nom de Saint-Rodrigue?", "De la paroisse Saint-Rodrigue, fondée en 1945 et nommée en l’honneur du cardinal Jean-Marie-Rodrigue Villeneuve, archevêque de Québec de 1931 à 1947."], ["Quelles sont les artères principales de Saint-Rodrigue?", "La 1re Avenue, le boulevard de l’Atrium et la 55e Rue, ainsi que les autoroutes Laurentienne et Félix-Leclerc, qui bordent le quartier."]],
  "saint-romuald": [["Où se trouve Saint-Romuald?", "Sur la rive sud du Saint-Laurent, face à Sillery, entre les rivières Chaudière et Etchemin. C’est l’un des quatre secteurs de l’arrondissement Les Chutes-de-la-Chaudière-Est, à Lévis."], ["D’où vient le nom de Saint-Romuald?", "Il vient de la paroisse de Saint-Romuald-d’Etchemin, nommée en l’honneur de saint Romuald, moine né à Ravenne au Xe siècle et fondateur des Camaldules."], ["Comment se rendre à Québec depuis Saint-Romuald?", "Par le pont de Québec ou le pont Pierre-Laporte, situés tout près, qui mènent à Sainte-Foy. L’autoroute 20 longe le sud du secteur."]],
  "saint-sacrement": [["Où se trouve le quartier Saint-Sacrement?", "Sur la colline de Québec, à l’ouest de Montcalm, entre le coteau Sainte-Geneviève et le boulevard René-Lévesque, dans l’arrondissement de La Cité-Limoilou. Il touche aussi Saint-Sauveur et l’arrondissement de Sainte-Foy–Sillery–Cap-Rouge."], ["D’où vient le nom de Saint-Sacrement?", "De la paroisse du Très-Saint-Sacrement, fondée en 1921, dont le nom honore le sacrement de l’Eucharistie. Les religieux du Très-Saint-Sacrement, établis dans le secteur en 1915, ont largement contribué à son développement."], ["Quels parcs se trouvent à Saint-Sacrement?", "Le parc Saint-Sacrement, avec sa piscine, son skatepark et son terrain de curling, le parc Holland, le parc des Saints-Martyrs-Canadiens et le parc Notre-Dame-de-Bellevue."]],
  "sainte-therese-de-lisieux": [["Où se trouve Sainte-Thérèse-de-Lisieux?", "Dans l’arrondissement de Beauport, aux limites nord-est de la ville de Québec, entre le boulevard Louis-XIV, Lac-Beauport et la rivière Montmorency."], ["D’où vient le nom de Sainte-Thérèse-de-Lisieux?", "De l’ancienne municipalité, qui adopte ce nom en 1945 à la place de Notre-Dame-de-la-Miséricorde-de-Beauport. Il évoque sainte Thérèse de Lisieux, à qui est dédiée l’église Sainte-Thérèse-de-l’Enfant-Jésus, construite en 1936."], ["Quels espaces verts se trouvent à Sainte-Thérèse-de-Lisieux?", "Le Centre de plein air de Beauport, en bordure de la rivière Montmorency, le parc de la Rivière-Beauport, le parc Jean-Guyon et, au nord, les monts Saint-Louis et Saint-André."]],
  "sillery": [["Où se trouve Sillery?", "Dans l’arrondissement Sainte-Foy–Sillery–Cap-Rouge, au sud de la ville de Québec, en bordure du fleuve Saint-Laurent."], ["D’où vient le nom de Sillery?", "Il honore Noël Brûlart de Sillery (1557-1640), chevalier de Malte et commandeur de Troyes, dont le don a permis aux Jésuites de fonder leur mission en 1637."], ["Quels parcs et espaces verts trouve-t-on à Sillery?", "Le parc du Bois-de-Coulonge, le domaine Cataraqui, la villa Bagatelle, la promenade Samuel-De Champlain et les parcs Ross, des Voiliers et de la Falaise."]],
  "trait-carre": [["Où se trouve le Trait-Carré?", "Dans l’arrondissement de Charlesbourg, à Québec, entre l’autoroute Laurentienne et le boulevard Henri-Bourassa, au sud du boulevard Jean-Talon."], ["D’où vient le nom du Trait-Carré?", "Du carré central de cinq arpents réservé à l’église, au presbytère et au cimetière lors de la fondation de Charlesbourg en 1665. Le nom a été officialisé en 1959."], ["Qu’est-ce que le site patrimonial de Charlesbourg?", "L’ancien noyau villageois du Trait-Carré, déclaré site patrimonial en 1965. Il couvre 24 ha et compte 138 bâtiments, dont l’église Saint-Charles-Borromée, classée en 1959."]],
  "val-belair": [["Où se trouve Val-Bélair?", "Dans le nord-ouest de la ville de Québec, dans l’arrondissement de La Haute-Saint-Charles, entre le quartier des Châtels et Sainte-Catherine-de-la-Jacques-Cartier, au pied des Laurentides."], ["D’où vient le nom de Val-Bélair?", "Il réunit les noms de Bélair et de Val-Saint-Michel, fusionnées en 1974. Bélair rappelle le fief de Bélair, concédé à Guillaume Bonhomme en 1682."], ["Comment se rendre à Val-Bélair?", "L’autoroute Henri-IV est l’accès le plus direct. La route Sainte-Geneviève, l’avenue Industrielle et la rue de Montolieu mènent au boulevard Pie-XI, et le Corridor des Cheminots, une piste cyclable, relie le quartier au centre-ville."]],
  "vanier": [["Où se trouve Vanier?", "Dans l’arrondissement des Rivières, à Québec, entre la rivière Saint-Charles et l’autoroute Félix-Leclerc, à l’ouest de l’autoroute Laurentienne. Il voisine Duberger–Les Saules à l’ouest et le secteur de Limoilou à l’est."], ["D’où vient le nom de Vanier?", "Il rappelle Georges P. Vanier, militaire, diplomate et gouverneur général du Canada. La ville de Québec-Ouest a adopté ce nom en juin 1966, à l’occasion de son jubilé d’or."], ["Vanier est-il encore une ville?", "Non. Vanier a été regroupée avec Québec le 1er janvier 2002. Malgré le référendum sur la défusion de 2004, elle est restée un quartier de Québec, dans l’arrondissement des Rivières."]],
  "vieux-bourg": [["Où se trouve le Vieux-Bourg?", "Dans le sud de l’arrondissement de Beauport, à Québec, entre la rivière Beauport et la rue Francheville, et entre le fleuve Saint-Laurent et l’autoroute Félix-Leclerc."], ["Qu’est-ce que le site patrimonial de Beauport?", "Un site déclaré en 1964 et agrandi en 1985, qui s’étend sur près de six kilomètres le long de l’avenue Royale. Il regroupe de nombreuses maisons anciennes, dont plusieurs dans le Vieux-Bourg."], ["Quelle est l’artère principale du Vieux-Bourg?", "L’avenue Royale, son artère commerciale et de circulation locale. Le quartier est aussi traversé par le boulevard Sainte-Anne, l’autoroute Dufferin-Montmorency, la rue Seigneuriale et le boulevard des Chutes."]],
  "vieux-moulin": [["Où se trouve le quartier du Vieux-Moulin?", "Dans l’ouest de l’arrondissement de Beauport, à Québec, entre la rivière Beauport et les arrondissements de La Cité-Limoilou et de Charlesbourg, au nord du fleuve Saint-Laurent."], ["D’où vient le nom du Vieux-Moulin?", "Le quartier partage son nom avec l’avenue du Vieux-Moulin, qui rappelle un moulin à farine construit par les Jésuites vers 1695 au bord du ruisseau du Moulin. Ce moulin a été détruit par le feu en 1948."], ["Quels anciens secteurs forment le Vieux-Moulin?", "Surtout l’ancienne municipalité de Giffard, qui a existé de 1912 à 1976, et celle de Saint-Michel-Archange, formée autour de l’hôpital aujourd’hui appelé Institut universitaire en santé mentale de Québec."]],
  "la-cite-limoilou": [["Quels quartiers font partie de La Cité-Limoilou?", "L’arrondissement compte neuf quartiers : Vieux-Québec–Cap-Blanc–colline Parlementaire, Saint-Roch, Saint-Jean-Baptiste, Montcalm, Saint-Sauveur, Saint-Sacrement, Lairet, Maizerets et Vieux-Limoilou."], ["Le Vieux-Québec est-il dans La Cité-Limoilou?", "Oui. Le Vieux-Québec, au sommet et au pied du cap Diamant, fait partie du quartier Vieux-Québec–Cap-Blanc–colline Parlementaire, qui est le centre-ville et le centre historique de l’arrondissement."], ["D’où vient le nom Limoilou?", "Le nom est une variante de Limoëlou, le manoir de Jacques Cartier à Saint-Malo, en Bretagne. Les villages ouvriers au nord de la rivière Saint-Charles l’adoptent en 1893."]],
  "les-rivieres": [["Quels quartiers font partie de l’arrondissement des Rivières?", "L’arrondissement compte trois quartiers : Vanier, Duberger–Les Saules et Neufchâtel-Est–Lebourgneuf."], ["D’où vient le nom Les Rivières?", "Le nom rappelle la rivière Saint-Charles, qui traverse l’arrondissement, et deux de ses affluents, la rivière du Berger et la rivière Lorette."], ["D’où vient le nom Lebourgneuf?", "Il réunit les dernières lettres de Charlesbourg et les premières de Neufchâtel, les deux secteurs situés de part et d’autre du quartier. L’ancienne municipalité de Charlesbourg-Ouest prend ce nom en 1988."]],
  "sainte-foy-sillery-cap-rouge": [["Quels quartiers font partie de Sainte-Foy–Sillery–Cap-Rouge?", "L’arrondissement compte sept quartiers : Cité-Universitaire, Sillery, Saint-Louis, Plateau, Pointe-de-Sainte-Foy, l’Aéroport et Cap-Rouge."], ["Où se trouve l’Université Laval?", "Dans le quartier Cité-Universitaire, à Sainte-Foy. Le campus, commencé en 1949, s’étendait autrefois sur les territoires de Sainte-Foy et de Sillery."], ["D’où vient le nom Cap-Rouge?", "Il vient du schiste rougeâtre des falaises et du cap qui domine le fleuve, à l’embouchure de la rivière du Cap Rouge."]],
  "wendake": [["Où se trouve Wendake?", "Dans le nord de la ville de Québec, qui l’entoure complètement. Wendake touche les secteurs de Loretteville, Lac-Saint-Charles et Saint-Émile, dans l’arrondissement de La Haute-Saint-Charles."], ["Que veut dire Wendake?", "Wendake signifie « chez les Wendats ». Dans la région des Grands Lacs, les Hurons étaient appelés Wendats, un nom qui signifie « les habitants de l’île ou de la péninsule »."], ["Que visiter à Wendake?", "Dans le Vieux-Wendake, le Musée huron-wendat, l’Hôtel-Musée Premières Nations, l’église Notre-Dame-de-Lorette, la maison Tsawenhohi et la chute Kabir Kouba. On y trouve aussi de nombreuses boutiques d’artisanat."]],
  "lac-delage": [["Où se trouve Lac-Delage?", "Au nord de Québec, dans la MRC de La Jacques-Cartier. La ville touche le secteur de Lac-Saint-Charles, à Québec, au sud, et Stoneham-et-Tewkesbury au nord-est."], ["D’où vient le nom Lac-Delage?", "Il rend hommage à Cyrille Fraser Delâge, sénateur et député mort deux ans avant la création de la ville, en 1959. Auparavant, le lac s’appelait lac Larron."], ["Que faire à Lac-Delage?", "Le Manoir du Lac Delage accueille les visiteurs, et le centre Empire 47 est consacré au vélo de montagne. Des événements annuels de vélo s’y tiennent, comme XTerra et Popcycle47, consacré au fatbike."]],
  "saint-gabriel-de-valcartier": [["Où se trouve Saint-Gabriel-de-Valcartier?", "Au nord de Québec, à environ 25 km du centre-ville, dans la MRC de La Jacques-Cartier. La municipalité touche l’arrondissement de La Haute-Saint-Charles, à Québec, au sud."], ["D’où vient le nom Valcartier?", "Valcartier joint les mots val et Cartier, car le territoire occupe une vallée formée par la rivière Jacques-Cartier. Saint-Gabriel rappelle l’ancienne seigneurie de Saint-Gabriel."], ["Qu’est-ce que le Village Vacances Valcartier?", "Un complexe de loisirs de Saint-Gabriel-de-Valcartier, avec un grand parc aquatique l’été et des glissades l’hiver. Un hôtel de glace y est aussi installé chaque hiver."]],
  "fossambault-sur-le-lac": [["Où se trouve Fossambault-sur-le-Lac?", "Au nord-ouest de Québec, dans la MRC de La Jacques-Cartier, autour de la partie sud du lac Saint-Joseph. La ville touche Sainte-Catherine-de-la-Jacques-Cartier, Shannon et Lac-Saint-Joseph."], ["D’où vient le nom Fossambault?", "Il rend hommage à Jacques Nau de La Boissière et de Fossambault, conseiller du roi et trésorier des finances en Berry, en France."], ["Quels attraits trouve-t-on près de Fossambault-sur-le-Lac?", "Le lac Saint-Joseph, où la Corporation nautique de Fossambault organise l’été des activités de voile, de kayak et de natation pour les jeunes. Tout près, la station touristique Duchesnay a des sentiers de randonnée, de ski de fond et de raquette."]],
  "lac-saint-joseph": [["Où se trouve Lac-Saint-Joseph?", "Au nord-ouest de Québec, dans la MRC de La Jacques-Cartier. La ville borde le lac Saint-Joseph à l’ouest, au nord et à l’est, alors que Fossambault-sur-le-Lac en occupe la partie sud-est."], ["D’où vient le nom Lac-Saint-Joseph?", "La ville porte le nom du lac qu’elle borde. Ce nom figure sur des cartes dès le XVIIe siècle, et le lac a aussi été appelé Ontaritzi et Grand lac des Vents."], ["Qu’est-ce que la station touristique Duchesnay?", "Un parc de villégiature de la Sépaq qui s’étend sur 89 km² autour du lac Saint-Joseph. On y fait de la randonnée, du ski de fond, de la raquette et du canot, et on peut y loger à l’Auberge Duchesnay ou en refuge."]],
  "sainte-petronille": [["Où se trouve Sainte-Pétronille?", "À la pointe sud-ouest de l’île d’Orléans, dans la MRC de L’Île-d’Orléans. Le village fait face au Vieux-Québec et à Lévis, et il touche à Saint-Pierre et à Saint-Laurent."], ["Comment se rendre à Sainte-Pétronille depuis Québec?", "L’autoroute 40 mène à Beauport, où la route 368 traverse le pont de l’Île-d’Orléans. Une fois sur l’île, à Saint-Pierre, le chemin Royal mène au village, vers le sud-ouest."], ["D’où vient le nom Sainte-Pétronille?", "Pétronille est une martyre romaine du Ier siècle. Selon la légende, elle était la fille, réelle ou spirituelle, de saint Pierre, patron de la paroisse mère. Le village s’est appelé Beaulieu de 1874 à 1980."]],
  "saint-pierre-de-l-ile-d-orleans": [["Où se trouve Saint-Pierre-de-l’Île-d’Orléans?", "Dans l’ouest de l’île d’Orléans, à l’arrivée du pont qui part de Beauport. La municipalité est entre Sainte-Pétronille et Sainte-Famille, dans la MRC de L’Île-d’Orléans."], ["Où est enterré Félix Leclerc?", "Au cimetière de Saint-Pierre-de-l’Île-d’Orléans, où il a vécu ses dernières années. L’Espace Félix-Leclerc, à l’entrée du village, présente son œuvre et donne accès à des sentiers de randonnée."], ["Quelle est la plus vieille église de l’île d’Orléans?", "L’ancienne église de Saint-Pierre, construite entre 1717 et 1719. Classée depuis 1958, elle n’accueille plus le culte. Une église moderne a été bâtie à côté en 1955."]],
  "saint-laurent-de-l-ile-d-orleans": [["Où se trouve Saint-Laurent-de-l’Île-d’Orléans?", "Sur la côte sud de l’île d’Orléans, à environ 11 km à l’est de Sainte-Pétronille. La municipalité fait partie de la MRC de L’Île-d’Orléans."], ["Que voir à Saint-Laurent-de-l’Île-d’Orléans?", "Le Musée maritime de l’île d’Orléans, avec la chalouperie Godbout de 1837, et l’église de 1860. Le quai et la marina donnent accès au fleuve."], ["D’où vient le nom Saint-Laurent?", "La paroisse s’appelait Saint-Paul jusqu’en 1698. Elle a pris le nom de saint Laurent, diacre de Rome, à la demande de François Berthelot, comte de Saint-Laurent, alors propriétaire de l’île."]],
  "sainte-famille-de-l-ile-d-orleans": [["Où se trouve Sainte-Famille-de-l’Île-d’Orléans?", "Sur la côte nord-est de l’île d’Orléans, entre Saint-Pierre et Saint-François, face à la Côte-de-Beaupré. C’est le chef-lieu de la MRC de L’Île-d’Orléans."], ["Quelle est la plus ancienne paroisse de l’île d’Orléans?", "Sainte-Famille, fondée en 1661. Elle a été la seule paroisse de l’île jusqu’en 1679."], ["Peut-on visiter la maison Drouin?", "Oui. Bâtie vers 1730, la maison Drouin appartient à la Fondation François-Lamy, qui en a fait un centre d’interprétation ouvert au public. Elle se trouve au 2958, chemin Royal, près de la limite avec Saint-François."]],
  "saint-jean-de-l-ile-d-orleans": [["Où se trouve Saint-Jean-de-l’Île-d’Orléans?", "Sur la côte sud de l’île d’Orléans, entre Saint-Laurent et Saint-François. Le village est à environ 26 km à vol d’oiseau au nord-est de Québec."], ["Qu’est-ce que le manoir Mauvide-Genest?", "Un manoir seigneurial érigé en 1734 pour le chirurgien Jean Mauvide et son épouse, Marie-Anne Genest. Lieu historique national du Canada depuis 1993, il abrite un centre d’interprétation sur le régime seigneurial."], ["D’où vient le nom Saint-Jean?", "Selon la Commission de toponymie, le nom évoquerait Jean de Lauson, sénéchal de la Nouvelle-France, mort à l’embouchure de la rivière Maheu en 1661. Il pourrait aussi venir de saint Jean-Baptiste, patron de la paroisse."]],
  "saint-francois-de-l-ile-d-orleans": [["Où se trouve Saint-François-de-l’Île-d’Orléans?", "À la pointe nord-est de l’île d’Orléans, à quelque 40 km en aval de Québec. La municipalité touche à Sainte-Famille et à Saint-Jean et fait face aux îles Madame et au Ruau."], ["Que voir à Saint-François-de-l’Île-d’Orléans?", "La tour d’observation, la plage et l’église de 1734. La maison Drouin, à Sainte-Famille, se trouve tout près de la limite municipale."], ["D’où vient le nom Saint-François?", "Il rappelle François Berthelot, seigneur de l’île d’Orléans au moment de la création de la paroisse, et saint François de Sales. La paroisse a été érigée en 1714 sous le nom de Saint-François-de-Sales."]],
  "l-ange-gardien": [["Où se trouve L’Ange-Gardien?", "Sur la Côte-de-Beaupré, à environ 18 km au nord-est de Québec, entre Boischatel et Château-Richer. La municipalité fait face à l’île d’Orléans."], ["Comment se rendre à L’Ange-Gardien depuis Québec?", "Par la route 138 (boulevard Sainte-Anne) ou par l’avenue Royale, qui traversent Beauport et Boischatel. Le centre-ville de Québec est à environ 20 minutes."], ["D’où vient le nom L’Ange-Gardien?", "En 1664, Mgr de Laval érige la paroisse des Saints-Anges-Gardiens. La chapelle, baptisée en 1670, reprend le nom au singulier, et la municipalité en hérite."]],
  "chateau-richer": [["Où se trouve Château-Richer?", "Sur la Côte-de-Beaupré, à l’est de Québec, entre L’Ange-Gardien et Sainte-Anne-de-Beaupré. C’est le chef-lieu de la MRC de La Côte-de-Beaupré."], ["D’où vient le nom Château-Richer?", "Son origine reste incertaine. Le nom figure sur une carte de Jean Bourdon au début des années 1640 et désignait le promontoire de l’église. La Commission de toponymie juge fantaisistes les légendes d’un dénommé Richer qui aurait appelé sa cabane un château."], ["Que voir à Château-Richer?", "L’avenue Royale et ses maisons anciennes, l’église de La Visitation-de-Notre-Dame et le moulin à eau du Petit-Pré. La chapelle Gravel, construite en 1941, se trouve aussi sur l’avenue Royale."]],
  "sainte-anne-de-beaupre": [["Où se trouve Sainte-Anne-de-Beaupré?", "Sur la Côte-de-Beaupré, à environ 23 km à l’est de Québec, face à l’île d’Orléans. La ville est située entre Château-Richer et Beaupré, dans la MRC de La Côte-de-Beaupré."], ["Quand a lieu la fête de sainte Anne à la basilique?", "Le 26 juillet. C’est le principal rassemblement de l’année au sanctuaire et le point culminant d’une neuvaine."], ["D’où vient le nom Sainte-Anne-de-Beaupré?", "Selon la tradition, des marins bretons sauvés d’un naufrage y auraient fondé un sanctuaire dédié à sainte Anne. Beaupré renvoie à la seigneurie de Beaupré, un nom attesté depuis au moins 1636."]],
  "beaupre": [["Où se trouve Beaupré?", "Sur la Côte-de-Beaupré, à environ 40 km à l’est de Québec, au bord du Saint-Laurent. La ville est située entre Sainte-Anne-de-Beaupré et Saint-Joachim."], ["Le mont Sainte-Anne est-il à Beaupré?", "Oui. La montagne, haute de 803 m, et sa station de sports d’hiver se trouvent sur le territoire de Beaupré. Saint-Ferréol-les-Neiges occupe son versant est."], ["D’où vient le nom Beaupré?", "Il vient de la seigneurie et de la Compagnie de Beaupré, un nom attesté en 1636. On l’explique souvent par la belle prairie de la côte, le « beau pré » qu’auraient vu des marins bretons."]],
  "saint-joachim": [["Où se trouve Saint-Joachim?", "À l’extrémité est de la Côte-de-Beaupré, à l’est de Beaupré, au pied du cap Tourmente. On y arrive par la route 138 Est, puis par l’avenue Royale."], ["Que peut-on voir au cap Tourmente?", "La réserve nationale de faune du Cap-Tourmente protège les marais où s’arrêtent les grandes oies des neiges au printemps et à l’automne. On y trouve des sentiers pédestres, un centre d’interprétation et les vestiges de la ferme de Champlain."], ["D’où vient le nom Saint-Joachim?", "La paroisse honore saint Joachim, époux de sainte Anne selon la tradition. Le nom a été choisi parce que la paroisse s’est détachée de Sainte-Anne-de-Beaupré."]],
  "saint-ferreol-les-neiges": [["Où se trouve Saint-Ferréol-les-Neiges?", "Sur la Côte-de-Beaupré, à environ 48 km de Québec, juste au nord-est de Beaupré. Le village est sur les contreforts est du mont Sainte-Anne, à l’ouest de Saint-Tite-des-Caps."], ["D’où vient le nom Saint-Ferréol-les-Neiges?", "Il rend hommage à Jean Lyon de Saint-Ferréol, supérieur du Séminaire de Québec de 1726 à 1734. « Les Neiges » a été ajouté en 1969 pour souligner la prospérité apportée par le ski au mont Sainte-Anne."], ["Le mont Sainte-Anne est-il à Saint-Ferréol-les-Neiges?", "La station de ski alpin est sur le territoire de Beaupré. Saint-Ferréol-les-Neiges occupe le versant est de la montagne, et on y fait du ski de fond au Centre national d’entraînement Pierre-Harvey."]],
  "saint-tite-des-caps": [["Où se trouve Saint-Tite-des-Caps?", "Sur la Côte-de-Beaupré, à 14 km au nord-est de Saint-Joachim et à 32 km de Baie-Saint-Paul. La route 138 traverse la municipalité en direction de Charlevoix."], ["D’où vient le nom Saint-Tite-des-Caps?", "Saint Tite était un disciple de saint Paul. Les Caps désignent les rochers dénudés de la région des Caps, entre le cap Tourmente et Baie-Saint-Paul."], ["Qu’est-ce que la côte de la Miche?", "C’est la section de la route 138 qui monte vers Saint-Tite-des-Caps, à plus de 700 m d’altitude. Elle a été construite en 1953."]],
  "neuville": [["Où se trouve Neuville?", "Sur la rive nord du Saint-Laurent, à environ 30 km à l’ouest du centre-ville de Québec, dans la MRC de Portneuf. La ville est située entre Saint-Augustin-de-Desmaures et Donnacona."], ["Pourquoi le maïs de Neuville est-il réputé?", "Le sol riche et les terres en pente vers le fleuve, dont les pierres gardent la chaleur du soleil, permettent de semer plus tôt qu’ailleurs dans la région. Les producteurs cultivent plus de 20 variétés de maïs sucré, vendues entre autres dans les kiosques de la route 138."], ["D’où vient le nom Neuville?", "De Nicolas Dupont, anobli sous le nom de Neuville, qui achète la seigneurie en 1680. En toponymie française, Neuville signifie « domaine nouveau »."]],
  "lac-sergent": [["Où se trouve Lac-Sergent?", "Dans la MRC de Portneuf, à environ 40 km de Québec et à 10 km de Saint-Raymond. La ville entoure le lac Sergent, entre Saint-Raymond et Sainte-Catherine-de-la-Jacques-Cartier."], ["D’où vient le nom Lac-Sergent?", "La version la plus répandue évoque un vieux soldat, ancien sergent, qui vivait au bord du lac. Une autre hypothèse le rattache au mot serre-joint, un outil dont le lac aurait la forme."], ["Peut-on faire du vélo à Lac-Sergent?", "Oui. La Vélopiste Jacques-Cartier/Portneuf, aménagée sur une ancienne voie ferrée, traverse la ville. Longue de 68 km, elle relie Saint-Gabriel-de-Valcartier à Rivière-à-Pierre."]],
  "cap-sante": [["Où se trouve Cap-Santé?", "Dans la MRC de Portneuf, sur la rive nord du Saint-Laurent, entre Donnacona et Portneuf. La ville est le chef-lieu de la MRC."], ["D’où vient le nom Cap-Santé?", "Plusieurs explications existent. Selon la Commission de toponymie du Québec, il viendrait le plus probablement de l’ancien français santeif, qui veut dire salutaire, appliqué au cap. Une carte de 1689 désigne déjà l’endroit comme Cap Sante."], ["Qu’est-ce que le fort Jacques-Cartier?", "Un fort français construit en 1759 à l’embouchure de la rivière Jacques-Cartier, après la prise de Québec. L’armée française y a passé l’hiver avant la bataille de Sainte-Foy, et des vestiges sont encore visibles. Le site et le manoir Allsopp voisin sont classés depuis 1978."]],
  "saint-basile": [["Où se trouve Saint-Basile?", "Au cœur de la MRC de Portneuf, à quelques kilomètres au sud de Saint-Raymond, entre Pont-Rouge et Portneuf. La ville est à moins de 35 minutes de Québec."], ["D’où vient le nom Saint-Basile?", "Il honore saint Basile le Grand, évêque de Césarée et théologien grec du IVe siècle. Le nom vient de la paroisse religieuse, dont les registres s’ouvrent en 1847."], ["Que faire à Saint-Basile?", "Le Centre Nature offre une trentaine de kilomètres de sentiers pour la marche, la raquette, le vélo de montagne et le fatbike, ainsi que des glissades sur chambre à air l’hiver. Ses pistes longent la rivière Chaude et traversent érablières et forêts."]],
  "desjardins": [["Quels secteurs font partie de l’arrondissement de Desjardins?", "Trois secteurs : Pintendre, Saint-Joseph-de-la-Pointe-De Lévy et Lévis, qui englobe le Vieux-Lévis, Lauzon et Saint-David. L’arrondissement occupe l’est de la ville, entre la rivière Etchemin et Beaumont."], ["D’où vient le nom de l’arrondissement de Desjardins?", "Il rappelle Alphonse Desjardins (1854-1920), journaliste et fondateur des caisses populaires. Il a fondé à Lévis, en 1900, le mouvement coopératif qui porte son nom. Sa maison, à l’angle des rues Guenette et Mont-Marie, est aujourd’hui un centre d’interprétation."], ["Comment se rendre à Québec depuis l’arrondissement de Desjardins?", "La traverse Québec-Lévis part du quai Paquet, dans le Vieux-Lévis. En voiture, on rejoint les ponts de Québec et Pierre-Laporte, à l’ouest de la ville, par l’autoroute 20. La Société de transport de Lévis a aussi des trajets vers la Rive-Nord."]],
  "les-chutes-de-la-chaudiere-est": [["Quels secteurs font partie des Chutes-de-la-Chaudière-Est?", "Quatre secteurs de Lévis : Charny, Sainte-Hélène-de-Breakeyville, Saint-Jean-Chrysostome et Saint-Romuald. L’arrondissement s’étend entre la rivière Chaudière et la rivière Etchemin, du fleuve vers le sud."], ["Où voir les chutes de la Chaudière?", "Au parc des Chutes-de-la-Chaudière, accessible par la sortie 130 de l’autoroute 73. Une passerelle suspendue de 113 mètres, à 23 mètres au-dessus de la rivière, donne une vue sur les chutes, hautes de 35 mètres."], ["Comment se rendre à Québec depuis Saint-Romuald ou Charny?", "Par le pont de Québec, qui part de Saint-Romuald, ou par le pont Pierre-Laporte, tout près. Charny a aussi une gare de VIA Rail sur la ligne entre Montréal et les Maritimes."]],
  "les-chutes-de-la-chaudiere-ouest": [["Quels secteurs font partie des Chutes-de-la-Chaudière-Ouest?", "Trois secteurs de Lévis : Saint-Étienne-de-Lauzon, Saint-Nicolas et Saint-Rédempteur. L’arrondissement occupe l’ouest de la ville, à l’ouest de la rivière Chaudière."], ["Que voir dans le vieux Saint-Nicolas?", "Le site du patrimoine de Saint-Nicolas, sur la route Marie-Victorin, regroupe des maisons du XVIIIe et du XIXe siècle, dont la maison Pâquet, construite vers 1760, et la chapelle Notre-Dame-de-Grâce, de 1867. Il a été cité site patrimonial en 1987."], ["D’où vient le nom de Saint-Étienne-de-Lauzon?", "Il rappelle l’abbé Étienne Baillargeon, curé de Saint-Nicolas, qui a travaillé à la création de la paroisse. Le mot Lauzon rappelle l’ancienne seigneurie de Lauzon. De 1862 à 1937, le bureau de poste s’appelait Baillargeon."]],
  "beaumont": [["Où se trouve Beaumont?", "Sur la rive sud du Saint-Laurent, à environ 15 km à l’est de Lévis, à l’extrémité nord-ouest de la MRC de Bellechasse. L’autoroute 20 traverse la municipalité au sud du village."], ["Que voir à Beaumont?", "L’église Saint-Étienne, ouverte au culte en 1733, les chapelles de procession Sainte-Anne et de la Sainte-Vierge, classées monuments historiques en 1981, et le moulin de Vincennes, reconstruit en 2006. Le chemin du Domaine, qui suit la falaise, est bordé de maisons anciennes."], ["D’où vient le nom de Beaumont?", "Il rappelle Charles Couillard (1647-1715), sieur des Islets et de Beaumont, à qui Jean Talon a concédé la seigneurie en 1672. Jusqu’en 1998, le nom officiel de la municipalité était Saint-Étienne-de-Beaumont."]],
  "saint-charles-de-bellechasse": [["Où se trouve Saint-Charles-de-Bellechasse?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, à environ 20 km au sud-est de Lévis. Le village est traversé par la rivière Boyer et par les routes 218 et 279, et l’autoroute 20 y donne accès par les sorties 337 et 341."], ["D’où vient le nom de Saint-Charles-de-Bellechasse?", "La paroisse, fondée en 1749, est placée sous le patronage de saint Charles Borromée, en l’honneur du seigneur Charles Couillard. Comme la rivière Boyer traverse le territoire, on parlait aussi autrefois de Saint-Charles-de-la-Rivière-Boyer."], ["Quels attraits voir à Saint-Charles-de-Bellechasse?", "L’église Saint-Charles-Borromée, reconstruite entre 1827 et 1829 sur des plans de Thomas Baillairgé, deux chapelles de procession et l’hôtel de ville, logé dans l’ancien presbytère des années 1740. Le territoire compte aussi des vignobles, dont Le Ricaneux et le Domaine Bel-Chas."]],
  "saint-michel-de-bellechasse": [["Où se trouve Saint-Michel-de-Bellechasse?", "Sur la rive sud du Saint-Laurent, dans la MRC de Bellechasse, entre Beaumont et Saint-Vallier, face à l’île d’Orléans. La route 132 traverse le village."], ["D’où vient le nom de Saint-Michel-de-Bellechasse?", "La paroisse, érigée en 1678, porte le nom de l’archange saint Michel. Jusqu’en 1842, on parlait de Saint-Michel-de-la-Durantaye. Le mot Bellechasse a été ajouté en 1992 pour distinguer la municipalité de Saint-Michel, en Montérégie."], ["Que voir à Saint-Michel-de-Bellechasse?", "Le noyau villageois et ses maisons de bois, l’ensemble paroissial avec son presbytère de 1740 et son église de 1872, le sanctuaire Notre-Dame-de-Lourdes au bord du fleuve et le port de plaisance."]],
  "la-durantaye": [["Où se trouve La Durantaye?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, juste au sud de Saint-Michel-de-Bellechasse. La route 281 traverse le village et rejoint la route 132 au bord du fleuve."], ["D’où vient le nom La Durantaye?", "Il rappelle Olivier Morel de La Durantaye (1640-1716), capitaine du régiment de Carignan-Salières, qui a reçu en 1672 la seigneurie de La Durantaye. La paroisse et la municipalité se sont d’abord appelées Saint-Gabriel-Archange."], ["Que faire à La Durantaye?", "Visiter la place publique de l’église, avec le centre multifonctionnel aménagé dans l’ancienne église, son étang et le parc de l’Étang. Le lac aux Canards, autrefois appelé lac Saint-Michel, est un lieu de villégiature."]],
  "saint-gervais": [["Où se trouve Saint-Gervais?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, à environ 25 km au sud-est de Lévis. La route 279 traverse le village et le relie à Saint-Charles-de-Bellechasse."], ["Pourquoi parle-t-on de la Nouvelle-Cadie à Saint-Gervais?", "Après le Grand Dérangement de 1755, des familles acadiennes s’installent dès 1756 sur des terres appelées la Première Cadie. Avant l’ouverture de la paroisse en 1780, ce lieu nommé Nouvelle-Cadie regroupe une soixantaine de familles acadiennes."], ["D’où vient le nom de Saint-Gervais?", "De la paroisse Saint-Gervais-et-Saint-Protais, ouverte en 1780 et dédiée aux saints Gervais et Protais par le curé Louis-Pascal Sarault. Le nom abrégé Saint-Gervais est devenu le nom officiel de la municipalité en 1991."]],
  "saint-anselme": [["Où se trouve Saint-Anselme?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, à environ 25 km de Lévis. La rivière Etchemin traverse la municipalité, et la route 277 la relie à Saint-Henri."], ["D’où vient le nom de Saint-Anselme?", "En 1827, Mgr Panet, évêque de Québec, a placé la nouvelle paroisse sous le patronage de saint Anselme, archevêque de Canterbury, un saint qu’il vénérait particulièrement."], ["Que voir à Saint-Anselme?", "Les chutes Rouillard sur la rivière Etchemin, l’église bâtie entre 1846 et 1850, le presbytère aux dix-huit lucarnes et la cycloroute de Bellechasse, aménagée sur l’ancienne voie ferrée."]],
  "saint-vallier": [["Où se trouve Saint-Vallier?", "Sur la rive sud du Saint-Laurent, dans la MRC de Bellechasse en Chaudière-Appalaches. Le village est à 8 km à l’est de Saint-Michel-de-Bellechasse, face à l’île d’Orléans, et l’autoroute 20 y a une sortie (356)."], ["D’où vient le nom de Saint-Vallier?", "Il honore Mgr Jean-Baptiste de La Croix de Chevrières de Saint-Vallier, deuxième évêque de Québec et fondateur de l’Hôpital général de Québec. Il a servi d’intermédiaire quand les religieuses de cet hôpital ont acquis la seigneurie, en 1720."], ["Que voir à Saint-Vallier?", "L’église de Saint-Philippe et Saint-Jacques, bâtie en 1932, et la maison du docteur Joseph-Côté, un cottage Regency classé. Le village compte aussi une fromagerie, une boulangerie artisanale et des ateliers d’artisans."]],
  "honfleur": [["Où se trouve Honfleur?", "Au cœur de la MRC de Bellechasse, en Chaudière-Appalaches, à environ 9 km au nord-est de Saint-Anselme. La municipalité est bordée par Saint-Gervais, Saint-Lazare-de-Bellechasse et Sainte-Claire."], ["D’où vient le nom de Honfleur?", "Il rappelle Honfleur, port de Normandie d’où Champlain est parti en 1603. Selon la Commission de toponymie, il évoque aussi Saint-Léonard-de-Honfleur, lieu d’origine de l’ancêtre du cardinal Louis-Nazaire Bégin."], ["Que trouve-t-on au village de Honfleur?", "L’église Notre-Dame-du-Bon-Conseil, bâtie en 1904, la bibliothèque La Livrothèque et la salle Fleur de Lys, qui peut accueillir jusqu’à 290 personnes."]],
  "saint-raphael": [["Où se trouve Saint-Raphaël?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, à une quinzaine de kilomètres du fleuve. La municipalité est au sud de Saint-Vallier et au nord de Saint-Nérée-de-Bellechasse."], ["D’où vient le nom de Saint-Raphaël?", "Il rend hommage à l’abbé François-Raphaël Paquet (1762-1836), curé de Saint-Gervais et premier desservant de la mission. La paroisse a été placée sous le patronage de saint Raphaël pour honorer sa mémoire."], ["Comment se rendre à Saint-Raphaël depuis l’autoroute 20?", "Prenez la sortie 348 et suivez la route 281 vers le sud. Elle passe par Saint-Michel-de-Bellechasse et La Durantaye avant d’arriver au village."]],
  "sainte-claire": [["Où se trouve Sainte-Claire?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, de part et d’autre de la rivière Etchemin. La municipalité touche Saint-Anselme à l’ouest, et la route 277 la traverse."], ["D’où vient le nom de Sainte-Claire?", "Le seigneur Gabriel-Elzéar Taschereau aurait choisi ce nom en mémoire de Claire-Françoise Bissot, épouse de Louis Jolliet, premier seigneur des lieux. La paroisse honore aussi sainte Claire d’Assise."], ["Quelle entreprise est née à Sainte-Claire?", "Le constructeur d’autocars Prevost, fondé par Eugène Prévost, natif de Sainte-Claire. L’entreprise, propriété de Volvo, exploite une usine d’assemblage dans la municipalité."]],
  "saint-lazare-de-bellechasse": [["Où se trouve Saint-Lazare-de-Bellechasse?", "Au centre de la MRC de Bellechasse, en Chaudière-Appalaches, à une trentaine de minutes de Lévis. La municipalité est le chef-lieu de la MRC."], ["D’où vient le nom de Saint-Lazare?", "Il rend hommage à Lazare Buteau (1749-1830), marchand de bois et major de milice à Saint-Gervais, qui avait promis de financer la construction de l’église. Son prénom est aussi celui de Lazare, l’ami de Jésus dans l’Évangile."], ["Qu’est-ce que le Festival de la Galette?", "Une fête consacrée à la galette de sarrasin, présentée en août à Saint-Lazare. Le sarrasin était autrefois très cultivé dans la municipalité, et le festival a tenu sa 50e édition en 2026."]],
  "saint-neree-de-bellechasse": [["Où se trouve Saint-Nérée-de-Bellechasse?", "Au centre de la MRC de Bellechasse, en Chaudière-Appalaches, à 23 km au sud de Saint-Vallier. La municipalité est entre Saint-Raphaël au nord et Saint-Damien-de-Buckland au sud-est."], ["D’où vient le nom de Saint-Nérée?", "Il honore l’abbé Joseph-Nérée Gingras (1825-1893), considéré comme le fondateur de la paroisse. Le patron, saint Nérée, est un martyr des premiers siècles, fêté avec saint Achillée."], ["Qu’est-ce que le lac Vert?", "Un lac d’environ 33 ha, autrefois appelé lac Saint-Nérée, bordé de nombreuses résidences. On y trouve le hameau du Lac-Vert et l’observatoire Alphonse-Tardif du Collège de Lévis."]],
  "saint-damien-de-buckland": [["Où se trouve Saint-Damien-de-Buckland?", "Dans le sud de la MRC de Bellechasse, en Chaudière-Appalaches, entre Saint-Lazare-de-Bellechasse à l’ouest et Armagh au nord-est. La route 279 traverse la municipalité."], ["D’où vient le nom de Saint-Damien-de-Buckland?", "Saint Damien est un médecin martyr, fêté avec son frère saint Côme. Buckland est le nom du canton créé en 1806, qui rappelle une localité d’Angleterre."], ["Qu’est-ce que la chapelle Sainte-Anne-des-Montagnes?", "Une chapelle de pèlerinage, appelée aussi chapelle du vœu, construite à la demande du curé Brousseau après qu’un feu eut épargné l’église. Rebâtie après l’incendie de 1905, elle est citée immeuble patrimonial par la municipalité."]],
  "saint-malachie": [["Où se trouve Saint-Malachie?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, au sud de Sainte-Claire et au nord-ouest de Saint-Nazaire-de-Dorchester. La route 277 traverse le village."], ["D’où vient le nom de Saint-Malachie?", "Il honore saint Malachie (1094-1148), archevêque d’Armagh, en Irlande, d’où venaient la plupart des premiers colons. Avant la création de la paroisse, l’endroit s’appelait East Frampton."], ["Qu’est-ce que La Crapaudière?", "C’est le surnom donné jadis à Saint-Malachie, à la suite d’une invasion de crapauds en 1873. La côte de la Crapaudière offre aujourd’hui une vue sur la vallée de l’Etchemin, et un crapaud figure dans les armoiries de la municipalité."]],
  "armagh": [["Où se trouve Armagh?", "Dans la MRC de Bellechasse, en Chaudière-Appalaches, au sud-est de Saint-Raphaël. La route 281 traverse la municipalité, à moins d’une heure de Québec."], ["D’où vient le nom d’Armagh?", "Du canton d’Armagh, créé en 1799, qui reprend le nom d’un comté de l’Ulster, en Irlande du Nord. Ce nom irlandais s’explique par le rôle des propriétaires terriens et des marchands irlandais dans la région."], ["Que faire au Parc des Chutes d’Armagh?", "Marcher ou faire de la raquette sur 5 km de sentiers, faire le parcours d’hébertisme et visiter le musée de la Gare en été. Le parc donne aussi accès à la Cycloroute de Bellechasse et aux sentiers de motoneige et de VTT."]],
  "saint-isidore": [["Où se trouve Saint-Isidore?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, à une quinzaine de kilomètres au sud de Lévis. La municipalité s’étend à l’est de la rivière Chaudière."], ["D’où vient le nom de Saint-Isidore?", "Il honore saint Isidore de Séville, évêque espagnol mort en 636, et non Isidore le Laboureur. La paroisse s’est d’abord appelée Saint-Isidore-de-Lauzon, d’après la seigneurie de Lauzon."], ["Comment se rendre à Saint-Isidore depuis Québec?", "Par l’autoroute Robert-Cliche (A-73), qui passe dans l’ouest de la municipalité, à 5 km du village. Les routes 173 (route du Président-Kennedy) et 275 (route Coulombe) traversent aussi le territoire."]],
  "sainte-henedine": [["Où se trouve Sainte-Hénédine?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, entre les rivières Chaudière et Etchemin. Le village est voisin de Saint-Isidore et à 14 km de Saint-Anselme."], ["D’où vient le nom de Sainte-Hénédine?", "Il rend hommage à Catherine-Hénédine Dionne, veuve du seigneur Pierre-Elzéar Taschereau et bienfaitrice de l’église. Sa sainte patronne, Hénédine, est une martyre de Sardaigne du IIe siècle. On dit aussi Sainte-Hénédine-de-Dorchester."], ["Que voir à Sainte-Hénédine?", "L’église, construite de 1910 à 1912, avec ses deux tours-clochers et son faux dôme octogonal. Avec le presbytère, le hangar à dîme et le cimetière, elle forme un site patrimonial cité par la municipalité."]],
  "saint-bernard": [["Où se trouve Saint-Bernard?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, à environ 35 km au sud de Québec. La rivière Chaudière borde le sud-est du territoire."], ["D’où vient le nom de Saint-Bernard?", "Il rappelle Bernard-Claude Panet (1753-1833), coadjuteur de Mgr Plessis lorsque la paroisse a été projetée, puis évêque de Québec à partir de 1825. Le seigneur Taschereau avait plutôt proposé saint Louis."], ["Quels parcs et sentiers trouve-t-on à Saint-Bernard?", "Le Boisé du Cap, avec ses sentiers et sa tour d’observation, le sentier du Moulin le long de la rivière des Îles Brûlées et la Halte de la Chaudière, ouverte l’été avec un accès à la rivière. Le village compte aussi plusieurs parcs, dont le parc du Faubourg et le Récré-O-Parc."]],
  "scott": [["Où se trouve Scott?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, à environ 35 km de Québec. Le territoire s’étend sur les deux rives de la rivière Chaudière, entre Saint-Isidore, Sainte-Hénédine, Saint-Bernard et Sainte-Marie."], ["D’où vient le nom de Scott?", "Il vient de la gare de Scott-Jonction, nommée en l’honneur de Charles Armstrong Scott. Avec Louis-Napoléon Larochelle, il a construit la première section du chemin de fer Lévis and Kennebec. La municipalité a longtemps porté le nom de Scott-Jonction."], ["Comment se rendre à Scott depuis Québec?", "Par l’autoroute Robert-Cliche (A-73), qui dessert la municipalité, ou par la route du Président-Kennedy (route 173). La route 171, qui longe la Chaudière, rejoint aussi Scott depuis Lévis."]],
  "sainte-marguerite": [["Où se trouve Sainte-Marguerite?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, à 12 km au nord de Sainte-Marie et à environ 45 km de Québec. Elle est voisine de Sainte-Hénédine et de Frampton."], ["D’où vient le nom de Sainte-Marguerite?", "Il honore Marguerite Marcoux, veuve de Lazare Buteau, qui a donné en 1830 le terrain de la fabrique. La paroisse a été placée sous le patronage de sainte Marguerite, reine d’Écosse."], ["Quel festival a lieu à Sainte-Marguerite?", "Le Demolition fest, le principal festival de la municipalité, se tient la dernière fin de semaine de mai."]],
  "saint-elzear": [["Où se trouve Saint-Elzéar?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, à 7 km de Sainte-Marie et à 56 km de Québec. Le village est bâti sur une colline, près de la rivière Beaurivage."], ["D’où vient le nom de Saint-Elzéar?", "Il honore Henri-Elzéar Juchereau Duchesnay (1809-1871), seigneur de Sainte-Marie, conseiller législatif et sénateur. La paroisse s’appelait d’abord Saint-Elzéar-de-Linière, en rappel de la famille Taschereau de Linière."], ["Que faire à Saint-Elzéar?", "Visiter l’église classée, bâtie de 1852 à 1854, observer le ciel à l’observatoire du Mont-Cosmos ou marcher dans ses sentiers. Les Fêtes de chez nous ont lieu chaque année la fin de semaine de la fête du Travail."]],
  "frampton": [["Où se trouve Frampton?", "Sur la Rive-Sud, dans la MRC de La Nouvelle-Beauce en Chaudière-Appalaches, entre les rivières Chaudière et Etchemin. Le village est à environ 10 km à l’est de Sainte-Marie."], ["D’où vient le nom de Frampton?", "Il vient du canton de Frampton, proclamé en 1806, qui rappelle une localité d’Angleterre, probablement celle du Dorset. La municipalité s’est appelée Saint-Édouard-de-Frampton jusqu’en 1997. Édouard rappelle Pierre-Édouard Desbarats, l’un des premiers concessionnaires du canton."], ["Que visiter à Frampton?", "Le Zoo Miller, où l’on voit une centaine d’animaux le long de sentiers, la microbrasserie Frampton Brasse et le Club de golf Dorchester, un parcours de 18 trous. L’ancien moulin à eau, construit en 1862, a été déplacé sur la route 275."]],
  "berthier-sur-mer": [["Où se trouve Berthier-sur-Mer?", "Sur la rive sud du Saint-Laurent, dans la MRC de Montmagny en Chaudière-Appalaches, à environ 60 km à l’est de Québec. Le village fait face à la pointe nord-est de l’île d’Orléans."], ["Comment aller à Grosse-Île depuis Berthier-sur-Mer?", "Des croisières guidées partent de la marina de Berthier-sur-Mer, au 100, rue de la Marina, de mai à octobre. Grosse-Île a servi de station de quarantaine de 1832 à 1937, et la visite se fait avec des guides de Parcs Canada."], ["Pourquoi le nom Berthier-sur-Mer?", "Berthier rappelle Alexandre Berthier, premier seigneur en 1672. Le nom actuel, adopté en 1971, distingue le village de Berthierville. Mer évoque la largeur du fleuve, sa salinité et ses marées à cet endroit."]],
  "saint-francois-de-la-riviere-du-sud": [["Où se trouve Saint-François-de-la-Rivière-du-Sud?", "Sur la Rive-Sud, dans la MRC de Montmagny en Chaudière-Appalaches, à environ 20 km au sud-ouest de Montmagny. Le village borde la rivière du Sud, au sud de l’autoroute 20."], ["D’où vient le nom de Saint-François-de-la-Rivière-du-Sud?", "La rivière du Sud traverse la municipalité. Le nom d’origine, Saint-François-de-Sales, évoque saint François de Sales, et la Commission de toponymie mentionne aussi Mgr François de Laval, premier évêque de Québec."], ["Qu’est-ce que le site patrimonial de Saint-François?", "Un ensemble religieux classé en 1988, au centre du village. Il comprend l’ancien presbytère de 1763, le calvaire, l’église Saint-François-de-Sales, l’ancien couvent de 1883 et le presbytère de 1887."]],
  "saint-pierre-de-la-riviere-du-sud": [["Où se trouve Saint-Pierre-de-la-Rivière-du-Sud?", "Sur la Rive-Sud, dans la MRC de Montmagny en Chaudière-Appalaches, entre Montmagny et Saint-François-de-la-Rivière-du-Sud. La rivière du Sud longe le nord de son territoire."], ["Que s’est-il passé à la bataille de Saint-Pierre?", "Le 25 mars 1776, pendant le siège de Québec par l’Armée continentale, des forces favorables aux Américains ont mis en déroute des miliciens loyalistes près du village. Les deux camps étaient formés en grande partie de miliciens canadiens."], ["Quelles personnalités sont nées à Saint-Pierre-de-la-Rivière-du-Sud?", "L’abbé Maurice Proulx, pionnier du cinéma documentaire au Québec, y est né en 1902. Augustin-Magloire Blanchet, né en 1797, est devenu évêque de Walla Walla, puis de Nesqually, aujourd’hui l’archidiocèse de Seattle."]],
  "saint-agapit": [["Où se trouve Saint-Agapit?", "Sur la Rive-Sud, dans la MRC de Lotbinière, en Chaudière-Appalaches. La municipalité est au sud de Saint-Apollinaire et du secteur Bernières de Lévis, sur les bords de la rivière Noire."], ["Quels événements ont lieu à Saint-Agapit?", "L’Expo agricole, le rodéo et le Festival Country Lotbinière, présenté depuis 2015, se tiennent sur le site de la Société d’agriculture. La municipalité organise aussi le Festival du Flocon à la fin février et le Festi Week-end à la fin juin."], ["D’où vient le nom de Saint-Agapit?", "Il rappelle le pape Agapit, ou Agapet Ier, qui a régné de 535 à 536. La paroisse s’est d’abord appelée Saint-Agapit-de-Beaurivage, en souvenir de la seigneurie de Beaurivage. Ses habitants s’appellent les Agapitois et les Agapitoises."]],
  "saint-antoine-de-tilly": [["Où se trouve Saint-Antoine-de-Tilly?", "Sur la rive sud du Saint-Laurent, dans la MRC de Lotbinière, en Chaudière-Appalaches. Le village est à environ 25 km de Québec par la route 132, juste à l’ouest de Lévis."], ["Que visiter à Saint-Antoine-de-Tilly?", "L’église de 1788, classée monument historique, le manoir de Tilly, construit en 1786, et les maisons anciennes du chemin de Tilly. Le belvédère près de l’église et les plages en bordure du fleuve offrent de belles vues sur le Saint-Laurent."], ["D’où vient le nom de Saint-Antoine-de-Tilly?", "La paroisse honore saint Antoine de Padoue. Le nom Tilly rappelle Pierre-Noël Le Gardeur, sieur de Tilly, qui a acheté la seigneurie en 1700. Ses habitants s’appellent les Antoniens et les Antoniennes."]],
  "saint-gilles": [["Où se trouve Saint-Gilles?", "Sur la Rive-Sud, dans la MRC de Lotbinière, en Chaudière-Appalaches. La municipalité est à environ 20 minutes de Lévis et à 30 minutes de Québec."], ["Comment se rendre à Saint-Gilles depuis Québec?", "En voiture, on quitte l’autoroute 20 à Saint-Apollinaire ou à Saint-Étienne-de-Lauzon, à environ 20 km du village. En transport collectif, Express Lotbinière relie la salle municipale à Saint-Apollinaire, où une ligne mène au réseau de la STLévis."], ["D’où vient le nom de Saint-Gilles?", "Il vient de la seigneurie Saint-Gilles, concédée en 1738 à Gilles Rageot de Beaurivage, négociant de Québec. Ses habitants s’appellent les Gillois et les Gilloises."]],
  "saint-narcisse-de-beaurivage": [["Où se trouve Saint-Narcisse-de-Beaurivage?", "Sur la Rive-Sud, dans l’est de la MRC de Lotbinière, en Chaudière-Appalaches. Le village est à environ 20 minutes des ponts de Québec, à 22 km de Saint-Agapit et à 8 km de Saint-Bernard."], ["D’où vient le nom de Saint-Narcisse-de-Beaurivage?", "Il rappelle Narcisse Dionne, un marchand de Saint-Gilles et bienfaiteur de la paroisse. Beaurivage renvoie à la seigneurie dont faisait partie une bonne partie du territoire. Ses habitants s’appellent les Narcissiens et les Narcissiennes."], ["Pourquoi parle-t-on aussi de Neubois?", "C’est le nom du bureau de poste, ouvert en 1874 sous la forme Newbois et devenu Neubois en 1912. Selon une tradition, il viendrait de « Neuf-Bois », une jeune forêt de bouleaux poussée après un grand incendie. Une autre tradition le rattache à un village d’Alsace du même nom."]],
  "notre-dame-du-sacre-coeur-d-issoudun": [["Où se trouve Issoudun, dans Lotbinière?", "Sur la Rive-Sud, dans la MRC de Lotbinière, en Chaudière-Appalaches. Le village est à 7 km de Laurier-Station par la route 271 et à environ 40 km des ponts de Québec."], ["Pourquoi la municipalité s’appelle-t-elle Issoudun?", "Son nom officiel, Notre-Dame-du-Sacré-Coeur-d’Issoudun, rend hommage aux Missionnaires du Sacré-Coeur, arrivés au Québec en 1900 depuis Issoudun, dans l’Indre, en France. Ses habitants s’appellent les Issoudunois et les Issoudunoises."], ["Que faire à Issoudun?", "Le sentier La Tourbière, long de 4,2 km aller-retour, mène à un point de vue sur une tourbière de 150 hectares. Le musée Isidore-Boisvert présente environ 150 miniatures d’instruments agricoles et de voitures anciennes, et le vieux moulin à scie à vapeur se trouve rue Principale."]],
  "saint-patrice-de-beaurivage": [["Où se trouve Saint-Patrice-de-Beaurivage?", "Sur la Rive-Sud, dans la partie est de la MRC de Lotbinière, en Chaudière-Appalaches. La municipalité est entre Saint-Narcisse-de-Beaurivage, au nord, et Saint-Sylvestre, au sud, sur la route 269."], ["D’où vient le nom de Saint-Patrice-de-Beaurivage?", "Il honore saint Patrick, apôtre de l’Irlande, car l’église se trouvait dans le rang Saint-Patrice, peuplé d’Irlandais. Beaurivage rappelle la seigneurie concédée à Gilles Rageot de Beaurivage en 1738. Ses habitants s’appellent les Beaurivageois et les Beaurivageoises."], ["Quel est le lien entre Saint-Patrice-de-Beaurivage et Vachon?", "Joseph-Arcade Vachon et Rose-Anna Giroux Vachon, fondateurs de la boulangerie Vachon, ont quitté leur village natal de Saint-Patrice-de-Beaurivage en 1923. Ils se sont alors installés à Sainte-Marie, en Beauce."]],
  "laurier-station": [["Où se trouve Laurier-Station?", "Sur la Rive-Sud, au centre de la MRC de Lotbinière, en Chaudière-Appalaches. La municipalité est à 43 km au sud-ouest de Québec, le long de l’autoroute Jean-Lesage (20)."], ["D’où vient le nom de Laurier-Station?", "De la gare du chemin de fer, nommée en l’honneur de sir Wilfrid Laurier, premier ministre du Canada de 1896 à 1911. Selon la tradition, il s’y serait arrêté pendant une campagne électorale. Ses habitants s’appellent les Laurierlois et les Laurierloises."], ["Comment se rendre à Québec depuis Laurier-Station sans voiture?", "Les autobus d’Express Lotbinière relient Laurier-Station à Saint-Apollinaire en semaine. De là, la ligne orange rejoint le réseau de la STLévis, avec des correspondances vers Québec, par exemple vers l’Université Laval."]],
  "saint-flavien": [["Où se trouve Saint-Flavien?", "Sur la Rive-Sud, au centre de la MRC de Lotbinière, en Chaudière-Appalaches. Le village est juste au sud de Laurier-Station, sur la route 271."], ["Où vont à l’école les enfants de Saint-Flavien?", "Le préscolaire et le premier cycle du primaire se donnent à l’école de la Caravelle de Saint-Flavien, le 2e cycle à Joly et le 3e cycle à Dosquet. Au secondaire, les écoles les plus proches sont l’École Beaurivage, à Saint-Agapit, et l’École secondaire Pamphile-Le May, à Sainte-Croix."], ["D’où vient le nom de Saint-Flavien?", "Il honore Mgr Pierre-Flavien Turgeon (1787-1867), quatrième archevêque de Québec. Ses habitants s’appellent les Saint-Flaviennois et les Saint-Flaviennoises."]],
  "dosquet": [["Où se trouve Dosquet?", "Sur la Rive-Sud, dans la MRC de Lotbinière, en Chaudière-Appalaches. Le village est à 11 km au sud de l’autoroute 20, par la sortie 278, sur les routes 116 et 271."], ["D’où vient le nom de Dosquet?", "Il honore Mgr Pierre-Herman Dosquet (1691-1777), évêque de Québec de 1734 à 1739. La municipalité s’est appelée Saint-Octave-de-Dosquet jusqu’en 1996. Ses habitants s’appellent les Dosquetois et les Dosquetoises."], ["Peut-on faire du vélo à Dosquet?", "Oui. La Route verte traverse la municipalité le long de la route 116, sur l’ancienne voie ferrée que la MRC de Lotbinière a transformée en piste cyclable en 1998."]],
  "sainte-croix": [["Où se trouve Sainte-Croix?", "Sur la rive sud du Saint-Laurent, en Chaudière-Appalaches. C’est le chef-lieu de la MRC de Lotbinière, à une cinquantaine de kilomètres à l’ouest de Québec, en face de Portneuf, de Cap-Santé et de Donnacona."], ["Que visiter à Sainte-Croix?", "Le Domaine Joly-De Lotbinière, avec son manoir de 1851 et ses jardins, l’église terminée en 1915 et la chute du Petit Saut. Au printemps et à l’automne, des milliers d’oies blanches s’arrêtent sur les battures du fleuve."], ["D’où vient le nom de Sainte-Croix?", "Il rappelle la fête de l’Exaltation de la Sainte-Croix, le 14 septembre, jour où le père Jérôme Lalemant a pris possession de la seigneurie en 1647. Ses habitants s’appellent les San-cruciens et les San-cruciennes."]],
  "saint-sylvestre": [["Où se trouve Saint-Sylvestre?", "Sur la Rive-Sud, à l’extrémité sud-est de la MRC de Lotbinière, en Chaudière-Appalaches. Le village est à 6 km au sud de Saint-Patrice-de-Beaurivage, à 23 km de Sainte-Marie et à 37 km de Thetford Mines."], ["Qu’est-ce que le mont Radar?", "C’est le surnom du mont Sainte-Marguerite, le plus haut sommet de Saint-Sylvestre. Pendant la guerre froide, l’Aviation royale canadienne y a exploité une base de la ligne de radars Pinetree, jusqu’en 1964."], ["D’où vient le nom de Saint-Sylvestre?", "Il honore le pape Sylvestre Ier, fêté le 31 décembre. Selon la tradition, on a choisi le dernier saint de l’année parce que ces terres semblaient alors au bout du monde. Ses habitants s’appellent les Sylvestois et les Sylvestoises."]],
  "la-haute-saint-charles": [["Quels quartiers font partie de La Haute-Saint-Charles?", "L’arrondissement compte cinq quartiers : Loretteville, Val-Bélair, Lac-Saint-Charles, Saint-Émile et Des Châtels."], ["D’où vient le nom La Haute-Saint-Charles?", "Le nom rappelle que l’arrondissement occupe la partie haute du bassin versant de la rivière Saint-Charles, là où se trouve le lac Saint-Charles."], ["Quels parcs visiter dans La Haute-Saint-Charles?", "Le parc de la Falaise et de la chute Kabir Kouba, la réserve naturelle des Marais-du-Nord, le parc linéaire de la rivière Saint-Charles et le parc naturel du mont Bélair, à Val-Bélair."]],
  "l-ancienne-lorette": [["Où se trouve L’Ancienne-Lorette?", "Dans l’agglomération de Québec, en Capitale-Nationale. La ville est entièrement entourée par la ville de Québec, entre l’arrondissement des Rivières à l’est et celui de Sainte-Foy–Sillery–Cap-Rouge."], ["D’où vient le nom L’Ancienne-Lorette?", "Le nom rappelle le sanctuaire de Lorette, en Italie. Quand les Hurons-Wendats ont quitté la mission en 1697 pour la Jeune-Lorette, l’ancien village est devenu la Vieille-Lorette, puis L’Ancienne-Lorette."], ["L’aéroport Jean-Lesage est-il à L’Ancienne-Lorette?", "L’aéroport se trouve juste à l’ouest de la ville, sur un terrain qui appartenait autrefois à la paroisse de L’Ancienne-Lorette. Ce territoire fait partie de Québec depuis la fusion de la paroisse avec Sainte-Foy en 1971."]],
  "saint-augustin-de-desmaures": [["Où se trouve Saint-Augustin-de-Desmaures?", "Sur la rive nord du Saint-Laurent, à l’ouest de Québec. La ville est voisine de l’arrondissement Sainte-Foy–Sillery–Cap-Rouge à l’est et de Neuville à l’ouest."], ["D’où vient le nom Saint-Augustin?", "Le saint patron est Augustin d’Hippone. Il aurait été choisi pour honorer Augustin de Saffray de Mézy, gouverneur de la Nouvelle-France de 1663 à 1665, ou peut-être Paul Augustin Juchereau."], ["Comment se rendre à Saint-Augustin-de-Desmaures?", "Par l’autoroute 40 ou la route 138, qui traversent la ville d’est en ouest. La route 367, aussi appelée route de Fossambault, relie la route 138 au nord du territoire."]],
  "boischatel": [["Où se trouve Boischatel?", "Sur la Côte-de-Beaupré, à l’est de Québec, sur la rive est de la rivière Montmorency. La municipalité touche à l’arrondissement de Beauport et fait face à l’île d’Orléans."], ["La chute Montmorency est-elle à Boischatel?", "En partie. La rivière Montmorency forme la limite ouest de Boischatel, et une partie du parc de la Chute-Montmorency se trouve sur son territoire."], ["D’où vient le nom Boischatel?", "Le nom rend hommage à Jean-François de Beauchatel, premier aide de camp du général Montcalm. La municipalité s’appelait Saint-Jean-de-Boischatel avant de devenir Boischatel en 1991."]],
  "lac-beauport": [["Où se trouve Lac-Beauport?", "Au nord de Québec, dans la MRC de La Jacques-Cartier. La municipalité touche aux arrondissements de Charlesbourg et de Beauport au sud, à Stoneham-et-Tewkesbury au nord et à Sainte-Brigitte-de-Laval à l’est."], ["Que faire à Lac-Beauport?", "Du ski alpin au centre Le Relais, du ski de fond, de la raquette et du vélo de montagne aux Sentiers du Moulin, du golf au Mont-Tourbillon et de la baignade à la plage publique du lac Beauport."], ["D’où vient le nom Lac-Beauport?", "La municipalité porte le nom du lac Beauport, au sud de son territoire. Elle s’appelait Saint-Dunstan-du-Lac-Beauport jusqu’en 1989."]],
  "stoneham-et-tewkesbury": [["Où se trouve Stoneham-et-Tewkesbury?", "Dans la MRC de La Jacques-Cartier, à environ 25 km au nord du centre-ville de Québec, à la porte de la réserve faunique des Laurentides. La route 175 la traverse sur plus de 30 km."], ["Comment se rendre à Stoneham depuis Québec?", "Par la route 175, aménagée en autoroute à quatre voies jusqu’à Stoneham. Le trajet prend environ 20 minutes. Le Transport collectif de La Jacques-Cartier offre aussi un service vers Québec."], ["D’où vient le nom Stoneham-et-Tewkesbury?", "Stoneham vient de Stonham Aspal, dans le Suffolk, d’où venait le pasteur Philip Toosey. Tewkesbury est une localité du Gloucestershire, lieu d’origine de Kenelm Chandler, qui avait obtenu des terres dans la région en 1764."]],
  "sainte-brigitte-de-laval": [["Où se trouve Sainte-Brigitte-de-Laval?", "Dans la MRC de La Jacques-Cartier, à une trentaine de kilomètres au nord-est de Québec, dans la vallée de la rivière Montmorency."], ["Comment se rendre à Sainte-Brigitte-de-Laval?", "Par l’avenue Sainte-Brigitte, qui traverse la ville du nord au sud et constitue le seul accès direct vers Québec. La Traverse de Laval la relie aussi à Lac-Beauport."], ["D’où vient le nom Sainte-Brigitte-de-Laval?", "Sainte Brigitte d’Irlande, patronne de la paroisse érigée en 1863, rappelle l’origine irlandaise des premiers colons. Laval renvoie à François de Montmorency-Laval, premier propriétaire de la seigneurie de Beaupré."]],
  "sainte-catherine-de-la-jacques-cartier": [["Où se trouve Sainte-Catherine-de-la-Jacques-Cartier?", "Dans la MRC de La Jacques-Cartier, à environ 20 km à l’ouest de Québec. Elle est bordée par Shannon à l’est, Fossambault-sur-le-Lac au nord, ainsi que Pont-Rouge, Saint-Augustin-de-Desmaures et Québec au sud."], ["Quels sont les attraits de Sainte-Catherine-de-la-Jacques-Cartier?", "Le chemin de la Liseuse, une piste cyclable qui longe la rivière Jacques-Cartier, la station touristique Duchesnay et le parc de glisse du Grand-Héron, avec son anneau de glace de 2,7 km en forêt."], ["D’où vient le nom Sainte-Catherine-de-la-Jacques-Cartier?", "Sainte-Catherine évoque Catherine Nau de Fossambault, mère du premier seigneur, Alexandre Peuvret. La seconde partie du nom vient de la rivière Jacques-Cartier, qui traverse la ville."]],
  "shannon": [["Où se trouve Shannon?", "À environ 25 km au nord-ouest de Québec, dans la MRC de La Jacques-Cartier, dont elle est le chef-lieu. Elle est voisine de la base des Forces canadiennes Valcartier et de Sainte-Catherine-de-la-Jacques-Cartier."], ["D’où vient le nom de Shannon?", "Le nom rappelle l’origine irlandaise d’une grande partie de sa population, arrivée au XIXe siècle."], ["Quand Shannon a-t-elle été fondée?", "La municipalité est créée le 14 décembre 1946, à partir d’une partie du territoire de Sainte-Catherine de Portneuf. Elle est devenue une ville le 20 mai 2017."]],
  "levis": [["Où se trouve Lévis?", "Sur la rive sud du fleuve Saint-Laurent, directement en face de Québec, dans la région de la Chaudière-Appalaches. La ville s’étend entre Beaumont, à l’est, et Saint-Antoine-de-Tilly, à l’ouest."], ["Comment se rendre de Lévis à Québec?", "Par le pont de Québec ou le pont Pierre-Laporte, dans l’ouest de la ville, accessibles par l’autoroute 20 et la route 132. La Société de transport de Lévis offre aussi des trajets en autobus vers l’Université Laval et la colline Parlementaire."], ["D’où vient le nom de Lévis?", "La ville porte le nom de François Gaston de Lévis, héros de la bataille de Sainte-Foy en 1760. Bien avant, en 1629, Champlain avait nommé le cap de Lévy en l’honneur d’Henri de Lévis, vice-roi de la Nouvelle-France."]],
  "saint-henri": [["Où se trouve Saint-Henri?", "Sur la Rive-Sud, dans la MRC de Bellechasse en Chaudière-Appalaches, à environ 15 km de Lévis et 30 km de Québec. La municipalité touche Lévis au nord et La Nouvelle-Beauce à l’ouest."], ["D’où vient le nom de Saint-Henri?", "Le nom honore Henri II, empereur du Saint-Empire romain germanique. La municipalité est aussi connue sous le nom de Saint-Henri-de-Lévis."], ["Comment se rendre à Saint-Henri depuis Lévis?", "Par la route du Président-Kennedy (route 173), qui part du centre de Lévis et passe par Pintendre. La route 275 arrive aussi de Saint-Jean-Chrysostome."]],
  "saint-lambert-de-lauzon": [["Où se trouve Saint-Lambert-de-Lauzon?", "Dans la MRC de La Nouvelle-Beauce, en Chaudière-Appalaches, à environ 20 km au sud de Québec. La municipalité touche Lévis au nord, ainsi que Saint-Henri et Saint-Isidore à l’est."], ["D’où vient le nom de Saint-Lambert-de-Lauzon?", "Il honore Pierre Lambert, arpenteur qui a dressé les plans de la seigneurie de Lauzon en 1828. Lauzon rappelle cette seigneurie, qui appartenait à Jean de Lauzon."], ["Quelles routes traversent Saint-Lambert-de-Lauzon?", "L’autoroute Robert-Cliche (73) la traverse du nord au sud. Les routes 171 (rue Bellevue) et 175 (rue des Érables) y passent aussi, et la rue du Pont (route 218) sert d’axe est-ouest."]],
  "saint-apollinaire": [["Où se trouve Saint-Apollinaire?", "Sur la Rive-Sud, dans la MRC de Lotbinière, en Chaudière-Appalaches. La municipalité touche Lévis à l’est et se trouve à environ 20 km des ponts de Québec."], ["Comment se rendre à Québec depuis Saint-Apollinaire?", "Par l’autoroute Jean-Lesage (20) vers l’est, puis par le pont Pierre-Laporte ou le pont de Québec. En transport en commun, l’Express vers Sainte-Foy dessert la municipalité."], ["D’où vient le nom de Saint-Apollinaire?", "La municipalité honore Apollinaire de Ravenne, évêque martyr du IIe siècle et disciple de saint Pierre. Ses habitants s’appellent les Apollinairois et les Apollinairoises."]],
  "sainte-marie": [["Où se trouve Sainte-Marie?", "En Beauce, dans la région de Chaudière-Appalaches, à environ 40 km au sud de Québec. C’est le chef-lieu de la MRC de La Nouvelle-Beauce, accessible par l’autoroute 73."], ["Pourquoi Sainte-Marie est-elle associée aux gâteaux Vachon?", "L’entreprise Vachon a été fondée à Sainte-Marie en 1922. La Maison J.-A. Vachon, un centre d’interprétation, raconte son histoire."], ["Que visiter à Sainte-Marie?", "Le Domaine Taschereau, un parc écologique aménagé sur l’ancien domaine seigneurial, avec milieux humides et site ornithologique. On peut aussi visiter la Maison J.-A. Vachon, le Musée de l’aviation et l’économusée Le Forgeron d’or."]],
  "donnacona": [["Où se trouve Donnacona?", "Dans la MRC de Portneuf, région de la Capitale-Nationale, sur la rive nord du Saint-Laurent, à l’ouest de Québec. On y accède par l’autoroute 40 ou par le Chemin du Roy."], ["D’où vient le nom Donnacona?", "Du chef iroquoien Donnacona, qui vivait au village de Stadaconé, au bord de la rivière Saint-Charles, lors du passage de Jacques Cartier en 1535. Les habitants s’appellent les Donnaconiens et les Donnaconiennes."], ["Quelle place la papetière a-t-elle eue à Donnacona?", "L’usine, ouverte en 1912, a fait naître la ville et a employé plus de 1 500 hommes à son apogée. Elle a cessé sa production en 2008 et a été démolie à partir de 2011."]],
  "pont-rouge": [["Où se trouve Pont-Rouge?", "Dans la MRC de Portneuf, région de la Capitale-Nationale, au bord de la rivière Jacques-Cartier. La ville est voisine de Donnacona au sud et de Saint-Augustin-de-Desmaures à l’est."], ["Qu’est-ce que le moulin Marcoux?", "Un ancien moulin à eau en pierre, bâti vers 1870 à 1872 au bord de la rivière Jacques-Cartier, au 1, boulevard Notre-Dame. Restauré de 1974 à 1980, il est reconnu monument historique depuis 1978."], ["D’où vient le nom Pont-Rouge?", "Il rappelle le pont Rouge, un pont gratuit construit à côté du pont Royal, aujourd’hui le pont Déry, qui était à péage. La rue Dupont, elle, honore le curé Charles-François Dupont, en poste de 1917 à 1933."]],
  "saint-raymond": [["Où se trouve Saint-Raymond?", "Au centre de la MRC de Portneuf, dans la région de la Capitale-Nationale, à 25 km au nord de Donnacona. On l’appelle parfois Saint-Raymond-de-Portneuf."], ["Que faire dans la vallée Bras-du-Nord?", "La vallée se trouve à environ 10 km au nord de la ville. On peut y faire du canot, du kayak, de la randonnée et du vélo de montagne. Une coopérative locale gère le site."], ["Pourquoi appelle-t-on Saint-Raymond la « Ville de l’automobile »?", "Le surnom vient du grand nombre de concessionnaires automobiles installés dans la ville."]],
  "limoilou": [["Quelles sont les artères principales de Limoilou?", "La 1re Avenue, qui traverse le quartier du nord au sud, et la 3e Avenue, son artère commerçante. Le boulevard Wilfrid-Hamel, le boulevard des Capucins et le chemin de la Canardière le bordent ou le traversent."], ["Limoilou est-il un quartier de locataires?", "Oui. Au recensement de 2016, 75,8 % des habitants du Vieux-Limoilou étaient locataires."], ["D’où vient le nom Limoilou?", "Il rend hommage à Jacques Cartier, sieur de Limoëlou, premier Européen à y avoir mis le pied. La municipalité de Limoilou a été créée en 1893."]],
  "montcalm": [["Où se trouve le quartier Montcalm?", "Dans la haute-ville de Québec, à l’ouest du Vieux-Québec et du quartier Saint-Jean-Baptiste, dans l’arrondissement de La Cité-Limoilou."], ["Quelles sont les artères commerçantes de Montcalm?", "L’avenue Cartier et le boulevard René-Lévesque, entre l’avenue De Salaberry et l’avenue Bourlamaque, avec de nombreux restaurants, bars et petits commerces."], ["Quels parcs se trouvent à Montcalm?", "Une bonne partie des plaines d’Abraham, le parc des Braves, le parc Jacques-Marquette, le parc des Franciscains et le parc Lucien-Borne."]],
  "saint-roch": [["D’où vient le nom Saint-Roch?", "D’une chapelle que les Récollets dédient à saint Roch en 1692, alors qu’une épidémie frappe la colonie. Le nom passe ensuite à la rue, au faubourg, à la paroisse et au quartier."], ["Quels types de logements trouve-t-on à Saint-Roch?", "Des lofts et des condos dans d’anciens bâtiments industriels, des plex construits à la fin du XIXe siècle et des immeubles à logements des années 1940."], ["Comment Saint-Roch a-t-il changé?", "Depuis la fin des années 1990, le quartier est revitalisé : démolition du Mail Saint-Roch de 2000 à 2007, rénovation des façades et reconversion d’anciennes manufactures. Le nombre de personnes qui y travaillent a augmenté de 40 % entre 1996 et 2017."]],
  "saint-sauveur": [["D’où vient le nom Saint-Sauveur?", "De Jean Le Sueur, premier prêtre séculier de la Nouvelle-France, surnommé « Monsieur de Saint-Sauveur », qui y reçoit des terres en 1653."], ["Quels parcs trouve-t-on à Saint-Sauveur?", "Le parc Victoria, le parc Durocher, le parc Dollard-des-Ormeaux, le parc Alys-Robi et le parc linéaire des rivières Saint-Charles et du Berger, entre autres."], ["Quand Saint-Sauveur a-t-il été annexé à Québec?", "En 1889, après un référendum tenu les 26 et 27 septembre, à la suite d’un incendie qui avait détruit environ 500 maisons."]],
  "sainte-foy": [["Quand Sainte-Foy est-elle devenue une ville?", "Le 10 mars 1949. Elle a été fusionnée à la ville de Québec en 2002."], ["D’où vient le nom du chemin des Quatre-Bourgeois?", "Des quatre villas bâties par des notables au XIXe siècle le long de ce chemin : Mapple Cottage, Champlain Villa, Hazel Grove Cottage et New Prospect."], ["Quels sont les grands repères de Sainte-Foy?", "Le campus de l’Université Laval, le CHUL et les centres commerciaux du boulevard Laurier, dont Place Sainte-Foy et Place Laurier."]],
  "charlesbourg": [["Pourquoi Charlesbourg est-il appelé le village en étoile?", "En 1665, l’intendant Jean Talon y trace un village autour d’un carré central, le Trait-Carré, d’où les terres des colons rayonnent en étoile. C’est le seul village de ce type au Canada."], ["Quels quartiers composent Charlesbourg?", "Six quartiers : Notre-Dame-des-Laurentides, Des Jésuites, Orsainville, Bourg-Royal, Trait-Carré et Saint-Rodrigue."], ["Quels parcs trouve-t-on à Charlesbourg?", "Le parc de la Montagne-des-Roches, le parc des Moulins, le Domaine Notre-Dame-des-Bois, le parc Henri-Casault et le parc des Verveines, entre autres."]],
  "beauport": [["Quels quartiers composent Beauport?", "Cinq quartiers : Vieux-Moulin, Vieux-Bourg, Saint-Michel, Chutes-Montmorency et Sainte-Thérèse-de-Lisieux."], ["Où se trouve la chute Montmorency?", "À l’extrémité est de Beauport, à l’embouchure de la rivière Montmorency, dans le quartier des Chutes-Montmorency."], ["Quand Beauport a-t-elle été fusionnée à Québec?", "En 2002, lors des réorganisations municipales. Elle forme aujourd’hui l’arrondissement le plus à l’est de la ville."]],
  "lebourgneuf": [["D’où vient le nom Lebourgneuf?", "Il réunit la fin de « Charlesbourg » et le début de « Neufchâtel », les deux secteurs qui encadrent le quartier. Il est utilisé depuis 1988."], ["Dans quel arrondissement se trouve Lebourgneuf?", "Dans l’arrondissement des Rivières, au nord de l’autoroute Félix-Leclerc. Le quartier officiel s’appelle Neufchâtel-Est–Lebourgneuf."], ["Quels sont les grands axes de Lebourgneuf?", "L’avenue Chauveau et les boulevards Bastien, Lebourgneuf, Pierre-Bertrand et Robert-Bourassa, ainsi que les autoroutes Laurentienne et Félix-Leclerc."]],
  "vieux-quebec": [["Depuis quand le Vieux-Québec est-il inscrit à l’UNESCO?", "Depuis le 3 décembre 1985, comme site du patrimoine mondial."], ["Quelle est la différence entre la Haute-Ville et la Basse-Ville?", "La Haute-Ville, sur le cap Diamant, a une vocation militaire et administrative depuis 1620; la Basse-Ville, au pied du cap, s’est peuplée de commerçants et d’artisans."], ["Peut-on faire des travaux dans un logement du Vieux-Québec?", "Oui, mais les travaux sur les bâtiments sont encadrés, car le Vieux-Québec est un site patrimonial protégé par la Loi sur le patrimoine culturel."]]
};
